export const AUTO_LABELS = { certificate:'2년마다 자격증 준비', tutoring:'자녀 과외', lessons:'취미 레슨', checkup:'정기 건강 검진', childTuition:'자녀별 학비 결정', childMarriage:'자녀별 결혼 결정' };
const EDUCATION = {none:'아직 시작 전',primary:'초등 교육',secondary:'중등 교육',highschool:'고등 교육',vocational:'직업 교육',bachelor:'학사',master:'석사',doctorate:'박사'};
const HOME = {family:'가족과 거주',rent:'임차 주거',rented:'임차 주거',owned:'자가 주거',care:'돌봄 주거',carehome:'돌봄 주거'};
const CATEGORY = {birth:'출생',education:'배움',career:'일',family:'가족',relationship:'관계',finance:'재정',health:'건강',mobility:'이동',migration:'이동',community:'사회',hobby:'취미',hobbies:'취미',world:'세계',ending:'마지막',life:'생활',system:'생활',choice:'선택',goal:'계획'};
export const tr = (locale, ko, en) => locale === 'en' ? en : ko;
const badge = text => `<span class="pill">${escape(text)}</span>`;
const disabled = condition => condition ? 'disabled' : '';
const options = (entries, selected) => entries.map(([value,label]) => `<option value="${escape(value)}" ${String(value)===String(selected)?'selected':''}>${escape(label)}</option>`).join('');
export function countryName(id, locale='ko') { if(locale==='en') { try {return new Intl.DisplayNames(['en'],{type:'region'}).of(id);} catch {return id;} } return getCountry(id)?.name ?? id; }
export function countryOptions(selected='', includeRandom=true, locale='ko') { return (includeRandom?`<option value="random">${tr(locale,'가중 추첨으로 정하기','Weighted draw')}</option>`:'') + COUNTRIES.map(c=>`<option value="${escape(c.id)}" ${c.id===selected?'selected':''}>${escape(countryName(c.id,locale))}</option>`).join(''); }
export function stage(age) { return age<6?'작은 시작':age<13?'세상을 배우는 시절':age<19?'가능성을 찾는 시절':age<35?'나의 길을 만드는 시절':age<60?'삶을 넓혀 가는 시절':age<80?'속도를 다시 정하는 시절':'오래 간직한 시간'; }


function statRows(s) { return [['health','건강'],['happiness','행복'],['knowledge','지식'],['social','관계'],['energy','활력']].map(([key,label])=>`<div class="stat-row"><span>${label}</span><div class="meter"><span style="width:${Math.max(0,Math.min(100,Number(s.stats[key])||0))}%"></span></div><b>${Math.round(s.stats[key]??0)}</b></div>`).join(''); }
function overview(s,l) { const relatives=familyRoster(s).filter(p=>p.alive&&!['friend','partner','former_spouse'].includes(p.relation));return `<section class="life-overview" aria-label="현재 삶의 상태"><div class="identity-panel panel"><div class="identity-top">${portrait(s)}<div><h2>${escape(s.name)}</h2><div class="identity-meta">${escape(countryName(s.countryId,l))} · ${s.city==='urban'?'도시':'농촌'}</div><span class="pill accent">${escape(stage(s.age))}</span></div></div><div class="age-line"><strong class="age-number">${s.age}</strong><span>세</span><span class="year">${s.year}년</span></div><div class="stage-track" aria-label="생애 진행">${Array.from({length:10},(_,i)=>`<span class="${i<=s.age/11?'active':''}"></span>`).join('')}</div><div class="stats">${statRows(s)}</div></div><div class="scene-panel panel"><div class="scene-caption"><span class="eyebrow">A SCENE FROM YOUR LIFE</span><h2>${escape(s.career.retired?'한결 느려진 하루':s.education.program?'새로운 것을 배우는 날':s.career.jobId?'하루하루 쌓이는 시간':'아직 펼쳐지지 않은 길')}</h2><p>${escape(countryName(s.countryId,l))}의 ${s.city==='urban'?'도시':'마을'}, ${s.year}년</p></div>${scene(s)}<div class="scene-bottom"><span>현재의 자리 <strong>${escape(s.career.retired?'은퇴 생활':s.career.title)}</strong></span><span>${escape(EDUCATION[s.education.level]??s.education.level)}</span></div></div><div class="summary-panel panel"><div><span class="eyebrow">LIFE & RESOURCES</span><div class="balance">${escape(new Intl.NumberFormat('ko-KR').format(s.finance.cash))}<small>G</small></div><span class="hint">사용 가능한 생활 자금</span></div><div class="money-lines"><div><span>연간 수입</span><b>${amount(s.finance.annualIncome)}</b></div><div><span>연간 지출</span><b>${amount(s.finance.annualExpense)}</b></div><div><span>금융자산 · 일반 부채</span><b>${amount(s.finance.assets)} / ${amount(s.finance.debt)}</b></div></div><div class="family-summary"><div class="mini-divider"></div><span class="eyebrow">FAMILY IN YOUR STORY</span><div class="family-mini">${relatives.slice(0,7).map(p=>`<span class="family-dot" title="${escape(p.name)}">${escape(p.name?.slice(0,1)||'·')}</span>`).join('')||'<span class="hint">기록된 생존 가족 없음</span>'}</div><span class="hint">생존 가족 ${relatives.length}명</span></div><button class="text-button summary-link" data-tab="finance">재정 살펴보기 ↗</button></div></section>`; }
function decisions(s,vm,l) { const p=s.pending;const off=vm.busy||vm.readOnly||vm.viewing||s.status==='ended';return `<section class="decision-panel panel" aria-label="현재 결정"><div class="panel-title"><span class="eyebrow">${p?'A MOMENT TO CHOOSE':'THE YEARS BETWEEN'}</span>${p?`<button class="text-button" data-ui="minimize">${vm.minimized?'결정 다시 열기':'잠시 접어 두기'}</button>`:`<span class="pill">${s.year}년</span>`}</div>${isMilestoneReflection(s)&&!vm.minimized?reflectionDecision(s,vm):p&&!vm.minimized?`<h2 id="decision-title" tabindex="-1">${escape(p.title)}</h2><p>${escape(p.body)}</p><div class="choices">${p.choices.map((c,i)=>`<button type="button" class="choice" data-choice="${escape(c.id)}" data-decision="${escape(p.id)}" ${disabled(off)}><span class="choice-number">${String(i+1).padStart(2,'0')}</span><span class="choice-content"><strong>${escape(c.label)}</strong>${c.description?`<small>${escape(c.description)}</small>`:''}</span><span class="choice-arrow" aria-hidden="true">↗</span></button>`).join('')}</div>`:p?`<h2 id="decision-title" tabindex="-1">${escape(p.title)}</h2><p>다른 정보를 살펴보고 돌아오세요. 아직 선택하지 않은 결정은 이곳에 그대로 남습니다.</p><button class="secondary" data-ui="minimize" style="margin-top:18px">결정 다시 열기</button>`:`<div class="quiet-life"><div><h2 id="decision-title" tabindex="-1">${s.status==='ended'?'이 삶을 천천히 돌아보세요.':vm.playing?'지금, 삶이 흐르고 있습니다.':'잠시, 내 삶을 살펴보세요.'}</h2><p>${s.status==='ended'?'선택과 관계, 지나온 시간을 아래 기록에서 살펴볼 수 있습니다.':vm.playing?'한 해의 성장과 학업, 일과 생활이 이어집니다. 중요한 결정이 생기면 시간이 기다려 줍니다.':'시간 이어가기를 누르면 생활이 이어지고, 중요한 결정 앞에서 기다립니다. 원하는 변화는 아래 생활 메뉴에서 고를 수 있습니다.'}</p></div><span class="quiet-symbol" aria-hidden="true">⌁</span></div>`}</section>${flowControls(s,vm,l)}`; }
function familyRoster(s) {
  const descendants=people=>people.flatMap(person=>[person,...(Array.isArray(person.children)?descendants(person.children):[])]);
  return [...s.family.parents,...s.family.partners,...descendants(s.family.children),...s.family.friends,...(s.family.relationship?[s.family.relationship]:[])];
}
function familyVisibility(s,p) {
  const birth=getPersonBirthContext(s,p.id);
  return {birth,unknownAbsent:birth?.presentAtBirth===false&&Boolean(p.absent)};
}
function familyCard(s,p) {
  const {birth,unknownAbsent}=familyVisibility(s,p);
  const role=({parent:'부모',mother:'어머니',father:'아버지',partner:'교제 상대',cohabitant:'동거 상대',spouse:'배우자',former_spouse:'이전 배우자',late_spouse:'사별한 배우자',child:'자녀',grandchild:'손자녀',great_grandchild:'증손자녀',friend:'친구'})[birth?.role??p.relation]??p.relation??'가족';
  return `<div class="person-card ${p.alive?'':'deceased'}" data-family-detail-person-id="${escape(p.id)}"><span class="family-dot" aria-hidden="true">${unknownAbsent?'?':escape(p.name.slice(0,1))}</span><span>${escape(unknownAbsent?role:p.name)}<small>${unknownAbsent?'현재 부재':`${escape(role)} · ${p.alive?`${p.age}세`:`${p.deceasedAge??p.age}세에 사별`}`}</small>${unknownAbsent?'':familyContext(s,p)}</span></div>`;
}
function familyContext(s,p) {
  const notes=[];
  const birth=getPersonBirthContext(s,p.id);
  if(birth?.occupationLabel&&birth.presentAtBirth!==false)notes.push('출생 당시 직업: '+birth.occupationLabel+' (가상 설정)');
  if(p.absent)notes.push('따로 지내는 중');
  if(p.cohabiting)notes.push('동거 중');
  if(Number.isFinite(p.cohabitationStartedAge))notes.push('내 '+p.cohabitationStartedAge+'세에 동거 시작');
  if(p.premature)notes.push(p.age<=2?'조기 출생 · 성장 돌봄 중':'조기 출생 돌봄 기록');
  if(!p.alive&&p.deathCause)notes.push(p.deathCause);
  if(p.supportNeeds){
    const support=p.supportNeeds;
    notes.push(support.supported?'맞춤 접근성·돌봄 지원 중':'맞춤 지원이 필요한 생활');
    if(Number.isFinite(support.annualCost))notes.push('연간 지원비 '+amount(support.annualCost));
    if(Number.isFinite(support.lastPaidAge))notes.push('내 '+support.lastPaidAge+'세에 지원비 지출');
    if(Number.isFinite(support.lastShortfallAge))notes.push('내 '+support.lastShortfallAge+'세에 자금 부족');
    if(Number.isFinite(support.fundedYears))notes.push('실제 지원 '+support.fundedYears+'년');
    if(Number.isFinite(support.unmetYears)&&support.unmetYears>0)notes.push('지원 미충족 '+support.unmetYears+'년');
    if(support.lastPaidAge==null&&support.lastShortfallAge==null)notes.push('연간 지원 집행 기록 없음');
  }
  if(p.assignment)notes.push('파견 중 · '+p.assignment.yearsLeft+'년 남음');
  else if(p.awayUntil!=null)notes.push(p.awayUntil>s.age?'파견 중 · '+(p.awayUntil-s.age)+'년 뒤 복귀 예정':'파견 후 생활을 조정하는 중');
  if(p.business)notes.push('승계 사업 운영 · '+p.business.level+'단계');
  else if(p.businessInherited)notes.push('가업 승계 기록');
  if(p.education)notes.push('학력: '+(EDUCATION[p.education]??({college:'대학 재학'})[p.education]??p.education));
  if(p.adopted)notes.push('입양으로 이어진 가족');
  if(p.alive&&p.closeness!=null)notes.push('친밀도 '+Math.round(p.closeness));
  return notes.length?'<small class="person-context">'+notes.map(escape).join(' · ')+'</small>':'';
}
function details(s,tab) { const row=(label,value)=>`<div class="detail-stat"><small>${escape(label)}</small><strong>${escape(value)}</strong></div>`;if(tab==='education')return `<div class="detail-grid">${row('현재 학력',EDUCATION[s.education.level]??s.education.level)}${row('재학 과정',s.education.program?.label??'재학 중 아님')}${row('남은 학업',s.education.program?`${s.education.yearsLeft}년`:'—')}${row('현재 학업 상태',s.flags.educationOnLeave?'휴학 중 · 학업과 학비 정지':s.flags.educationPaused?'학비 부족으로 수강 보류':s.flags.educationFunding==='work-study'?'일·학업 병행':s.flags.educationFunding==='loan'?'부족 학비 대출 사용':s.education.program?'학업 진행 중':'재학 과정 없음')}</div>`;if(tab==='career')return `<div class="detail-grid">${row('직업',s.career.title)}${row('경력 / 공백',`${s.career.years}년 / ${s.career.breakYears}년`)}${row('급여 / 연금',`${amount(s.career.salary)} / ${amount(s.career.pension)}`)}</div>`;if(tab==='finance')return `<div class="detail-grid">${row('주거',HOME[s.finance.home]??s.finance.home)}${row('운용 전략',INVESTMENTS.find(x=>x.id===s.finance.allocation)?.label??s.finance.allocation)}${row('보험 / 식단',`${s.finance.insurance==='expanded'?'확대':'기본'} / ${({healthy:'건강',balanced:'균형',budget:'절약'})[s.finance.diet]??s.finance.diet}`)}${row('주택 가치 / 대출',`${amount(s.finance.homeValue)} / ${amount(s.finance.mortgage)}`)}${row('자동차 가치 / 할부',`${amount(s.flags.carValue??0)} / ${amount(s.flags.carLoan??0)}`)}${row('임대 주택',`${s.finance.rentals}채`)}${row('사업',s.finance.business?`${s.finance.business.level}단계 · 직원 ${s.finance.business.employees}명`:'운영하지 않음')}</div>`;if(tab==='health')return `<div class="detail-grid">${row('건강 상태',s.health.conditions.map(c=>c.name).join(', ')||'확인된 질환 없음')}${row('치료',typeof s.health.treatment==='object'?(s.health.treatment?.label??s.health.treatment?.name??(s.health.treatment?`${s.health.treatment.yearsLeft}년 남음`:'없음')):(s.health.treatment||'없음'))}${row('돌봄 필요',s.health.disability?'있음':'없음')}</div>`;if(tab==='mobility')return `<div class="detail-grid">${row('현재 국가',countryName(s.countryId))}${row('체류 자격',({citizen:'시민',temporary:'임시 체류',resident:'일반 거주',permanent:'영주',refugee:'난민 체류'})[s.migration.status]??s.migration.status)}${row('심사 / 체류 연수',`${s.migration.pending?'심사 중':'심사 없음'} · ${s.migration.years}년`)}</div>`;if(tab==='community')return communityDetails(s);if(tab==='hobbies')return `<div class="detail-grid">${s.hobbies.map(h=>row(HOBBIES.find(x=>x.id===h.id)?.label??h.id,`${h.level}단계`)).join('')||row('현재 취미','아직 선택 전')}</div>`;if(tab==='family'){const all=familyRoster(s);return `<div class="roster">${all.map(p=>familyCard(s,p)).join('')||'<p class="hint">아직 기록된 관계가 없습니다.</p>'}</div>`;}return ''; }
function selectedAction(s,a) { return a.selected??({study_field:s.flags.studyField??'general',study_destination:s.flags.studyDestination,insurance:s.finance.insurance,diet:s.finance.diet,allocate:s.finance.allocation,social_budget:String(s.finance.socialBudget),will:s.finance.will,auto_dinner:s.automations.dinner?'on':'off',move_city:s.city})[a.id]; }
export function normalizeGroup(group) { return ({relationship:'family',relationships:'family',social:'community',politics:'community',hobby:'hobbies',migration:'mobility',travel:'mobility',housing:'finance',business:'finance',money:'finance',work:'career',study:'education',care:'health'})[group]??group; }
function actions(s,vm,l) { const tab=GROUPS.find(g=>g[0]===vm.tab)??GROUPS[0],available=getAvailableActions(s).filter(a=>normalizeGroup(a.group)===tab[0]);return `<details class="systems-explorer panel" data-panel="systems" ${vm.panels?.systems?'open':''}><summary><span><strong>생활의 방향 바꾸기</strong><small>학업과 일상은 시간에 따라 이어집니다. 원할 때 행동을 선택하세요.</small></span><span class="explorer-toggle" aria-hidden="true">＋</span></summary><section class="systems-panel"><div class="system-tabs" role="tablist" aria-label="생활 시스템">${GROUPS.map(([id,ko,en])=>`<button type="button" class="tab-button" role="tab" id="tab-${id}" aria-selected="${id===tab[0]}" tabindex="${id===tab[0]?0:-1}" aria-controls="system-content" data-tab="${id}">${tr(l,ko,en)}</button>`).join('')}</div><div class="system-body" id="system-content" role="tabpanel" aria-labelledby="tab-${tab[0]}"><div class="system-intro"><div><h3 id="system-title" tabindex="-1">${tr(l,tab[1],tab[2])}의 선택</h3><p>${escape(tab[3])}</p></div>${badge(`${available.filter(a=>!a.disabledReason).length}개 가능`)}</div>${details(s,tab[0])}<div class="action-grid">${available.map(a=>{const reason=s.status==='ended'?'끝난 삶은 기록으로 보존됩니다.':vm.viewing?'보관된 삶은 읽기 전용입니다.':a.disabledReason;return `<form class="action-card ${reason?'unavailable':''}" data-action-form="${escape(a.id)}"><div class="action-title"><span>${escape(a.label)}</span><span class="action-cost">${Number.isFinite(a.cost)&&a.cost>0?amount(a.cost):'선택'}</span></div><p>${escape(a.description??'')}</p>${a.options?.length?`<label class="sr-only" for="option-${escape(a.id)}">${escape(a.label)} 세부 선택</label><select id="option-${escape(a.id)}" name="value" ${disabled(reason||vm.busy||vm.readOnly)}>${a.options.map(o=>`<option value="${escape(o.value)}" ${String(o.value)===String(selectedAction(s,a))?'selected':''}>${escape(o.label)}</option>`).join('')}</select>`:''}${reason?`<span class="disabled-reason">${escape(reason)}</span>`:''}<button type="submit" class="secondary" aria-label="${escape(a.label)} 선택하기" ${disabled(Boolean(reason)||vm.busy||vm.readOnly)}>선택하기 ↗</button></form>`;}).join('')||'<div class="empty">현재 이 시스템에 표시할 행동이 없습니다.<br>나이와 삶의 조건이 바뀌면 다시 살펴보세요.</div>'}</div></div></section></details>`; }
function sidebar(s,vm) { const off=vm.busy||vm.readOnly||vm.viewing||s.status==='ended',possible=getAvailableActions(s).filter(a=>!a.disabledReason&&a.id!=='goal_step'&&!a.options?.length);return `<aside class="side-stack"><details class="side-panel panel" data-panel="focus" ${vm.panels?.focus?'open':''}><summary>생활 초점 · ${escape(focusLabel(s))}</summary><h3>올해 마음을 둘 곳</h3><p>한 해의 생활 초점을 정하세요.<br>초점은 연간 성장과 생활에 영향을 줍니다.</p><div class="focus-list">${focusEntries(s).map(([key,label])=>`<button class="focus-button ${s.focus===key?'active':''}" data-focus="${key}" aria-pressed="${s.focus===key}" ${disabled(off)}>${label}</button>`).join('')}</div></details><details class="side-panel panel" data-panel="routines" ${vm.panels?.routines?'open':''}><summary>자동 응답과 반복 지출</summary><h3>흘러가는 일상</h3><label class="switch-row"><span>결정 자동 응답 (고급)<small>켜면 첫 번째 선택지를 대신 고릅니다. 생활 메뉴의 취업·교제·혼인까지 대신 실행하지는 않습니다.</small></span><input type="checkbox" data-setting="auto" ${s.settings.auto?'checked':''} ${disabled(off)}></label><details class="auto-details"><summary>반복 지출과 자녀 결정 관리</summary>${Object.entries(AUTO_LABELS).map(([key,label])=>`<label class="switch-row"><span>${label}<small>${s.automations.skipped?.[key]?`최근 ${escape(s.automations.skipped[key].age??'')}세 미실행: ${s.automations.skipped[key].reason==='insufficient_funds'?'자금 부족':'조건 미충족'}`:s.automations.lastRun?.[key]!==undefined?`최근 실행 ${escape(s.automations.lastRun[key])}세`:['childTuition','childMarriage'].includes(key)?'해당 조건에서 결정 카드 표시':'조건과 잔액을 확인해 연간 실행'}</small></span><input type="checkbox" data-setting="automations.${key}" ${s.automations[key]?'checked':''} ${disabled(off)}></label>`).join('')}</details></details><details class="side-panel panel plan-panel" data-panel="plan" ${vm.panels?.plan?'open':''}><summary>수동 계획 · ${s.goals.filter(g=>g.status==='active').length}개 진행 중</summary><h3>내가 적는 계획</h3><p>${escape(ADVISOR_STATUS.description??'외부 모델이 연결되지 않았습니다. 목표를 직접 적고 실행할 단계를 고르세요.')}</p><span class="pill accent">AI 미연결 · 수동 계획</span><form id="goal-form" class="goal-form"><label class="sr-only" for="goal-text">나의 계획</label><textarea id="goal-text" name="text" maxlength="500" placeholder="예: 일을 하며 공부할 시간을 만들고 싶다." ${disabled(off)}></textarea><label class="sr-only" for="goal-step-1">첫 번째 실행 단계</label><select id="goal-step-1" name="step1" ${disabled(off)}><option value="">실행할 행동 직접 선택</option>${possible.map(a=>`<option value="${escape(a.id)}">${escape(a.label)}</option>`).join('')}</select><label class="sr-only" for="goal-step-2">두 번째 실행 단계 (선택)</label><select id="goal-step-2" name="step2" ${disabled(off)}><option value="">두 번째 행동 (선택)</option>${possible.map(a=>`<option value="${escape(a.id)}">${escape(a.label)}</option>`).join('')}</select><button class="secondary" type="submit" ${disabled(off)}>계획 저장</button></form>${(s.goals??[]).map(g=>`<div class="goal-item"><strong>${escape(g.text)}</strong><p>${escape(({active:'진행 중',completed:'완료',cancelled:'취소',ended:'생애 종료로 마침'})[g.status]??'대기')} · ${g.cursor??g.index??g.completedSteps??0}/${g.steps.length}단계</p><div class="buttons"><button class="text-button" data-goal-step="${escape(g.id)}" ${disabled(off||['completed','cancelled'].includes(g.status))}>다음 단계 실행</button><button class="text-button" data-goal-cancel="${escape(g.id)}" ${disabled(off||['completed','cancelled'].includes(g.status))}>계획 취소</button></div></div>`).join('')}</details></aside>`; }

export function renderChart(points, key, {color='var(--accent)', label='합성 게임 수치', unit=''}={}) {
  if(!points.length)return '<div class="empty">시간이 흐르면 그래프가 그려집니다.</div>';
  const width=760,height=180,pad=35,vals=points.map(p=>{const v=typeof key==='function'?key(p):p[key];return typeof v==='number'&&Number.isFinite(v)?v:null;}),known=vals.filter(v=>v!==null);
  if(!known.length)return '<div class="empty">이 저장에는 해당 수치가 기록되지 않았습니다. 과거 값을 추정해 채우지 않습니다.</div>';
  const min=Math.min(0,...known),max=Math.max(1,...known),span=max-min;
  let segment=false;const path=vals.map((v,i)=>{if(v===null){segment=false;return '';}const x=pad+(width-pad*2)*i/Math.max(1,vals.length-1),y=height-pad-(v-min)/span*(height-pad*2),move=segment?'L':'M';segment=true;return move+x.toFixed(1)+','+y.toFixed(1);}).join(' ');
  const format=v=>new Intl.NumberFormat('ko-KR',{maximumFractionDigits:1}).format(v);
  return `<svg class="chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="${escape(label)}. 정확한 수치는 아래 표에서 확인할 수 있습니다."><path class="chart-axis" d="M${pad} ${pad}V${height-pad}H${width-pad}"/><path class="chart-axis" d="M${pad} ${height/2}H${width-pad}" stroke-dasharray="3 5"/><path class="chart-line" style="stroke:${color}" d="${path}"/>${vals.map((v,i)=>v===null?'':`<circle cx="${pad+(width-pad*2)*i/Math.max(1,vals.length-1)}" cy="${height-pad-(v-min)/span*(height-pad*2)}" r="2.5" fill="${color}"/>`).join('')}<text x="${pad}" y="${height-10}">${points[0]?.age??0}세</text><text x="${width-pad}" y="${height-10}" text-anchor="end">${points.at(-1)?.age??0}세</text><text x="${pad+7}" y="${pad-7}">${escape(format(max))}${escape(unit)}</text><text x="${pad+7}" y="${height-pad-7}">${escape(format(min))}${escape(unit)}</text></svg><details class="chart-data"><summary>${escape(label)} 수치 표 보기</summary><div class="table-scroll"><table><caption>${escape(label)} · 누락값은 미기록으로 표시</caption><thead><tr><th scope="col">나이</th><th scope="col">수치${unit?' ('+escape(unit)+')':''}</th></tr></thead><tbody>${points.map((p,i)=>`<tr><th scope="row">${p.age}세</th><td>${vals[i]===null?'미기록':escape(format(vals[i]))}</td></tr>`).join('')}</tbody></table></div></details>`;
}
function journalContent(s,vm) { const off=vm.busy||vm.readOnly||(vm.viewing&&s.status!=='ended'),tl=s.timeline??[];if(vm.journal==='map'){const selected=tl.find(x=>x.age===vm.mapAge)??tl.at(-1),events=s.history.filter(h=>h.age===selected?.age);return `<div class="journal-tools"><h3>한 칸에 담긴 일 년</h3><span class="hint">나이를 눌러 그해 기록 보기</span></div><div class="legend"><span><i style="background:#e5ebd9"></i>건강 65 이상</span><span><i style="background:#f5e1d4"></i>건강 40 미만</span><span>색상은 합성 건강 수치</span></div><div class="life-map">${tl.map(y=>`<button class="map-cell ${y.health>=65?'good':y.health<40?'low':''} ${y.age===selected?.age?'active':''}" data-map-age="${y.age}" title="${y.age}세 · ${y.year}년 · 건강 ${Math.round(y.health)} · 행복 ${Math.round(y.happiness)} · ${escape(s.history.filter(h=>h.age===y.age).map(h=>h.title).join(', ')||'평온한 해')}" aria-label="${y.age}세 · ${y.year}년 · 건강 ${Math.round(y.health)} · 행복 ${Math.round(y.happiness)}" aria-pressed="${y.age===selected?.age}">${y.age}<span>${y.year}</span></button>`).join('')}</div>${selected?`<div class="map-description"><strong>${selected.age}세 · ${selected.year}년 · ${escape(countryName(selected.countryId))}</strong><p>건강 ${Math.round(selected.health)} · 행복 ${Math.round(selected.happiness)} · 현금 ${amount(selected.cash)} · 부채 ${amount(selected.debt)}</p>${selected.environment?`<p>그해 합성 환경: ${selected.city==='urban'?'도시':selected.city==='rural'?'농촌':'생활 환경 미기록'} · 교육 ${selected.environment.education??'미기록'} · 건강 ${selected.environment.health??'미기록'}. 실제 국가 통계가 아닙니다.</p>`:'<p>이 저장에는 그해 생활 환경의 세부 값이 기록되지 않았습니다.</p>'}${events.map(e=>`<p>${escape(e.title)} — ${escape(e.text)}</p>`).join('')||'<p>큰 갈림길 없이 평온하게 흘러간 해였습니다.</p>'}</div>`:''}`;}if(vm.journal==='finance')return financeJournal(s,vm);if(vm.journal==='comparison')return comparisonJournal(s,off);const histories=s.history.filter(h=>!vm.historyFilter||h.category===vm.historyFilter).slice().reverse(),categories=[...new Set(s.history.map(h=>h.category))];return `<div class="journal-tools"><h3>지나온 시간의 흔적</h3><label><span class="sr-only">기록 분류</span><select id="history-filter"><option value="">모든 기록</option>${categories.map(k=>`<option value="${escape(k)}" ${vm.historyFilter===k?'selected':''}>${escape(CATEGORY[k]??k)}</option>`).join('')}</select></label></div><div class="timeline">${histories.slice(0,vm.historyLimit).map(h=>`<article class="timeline-item"><span class="timeline-age">${h.age}세</span><h4>${escape(h.title)}<small>${h.year} · 규칙</small></h4><p>${escape(h.text)}</p></article>`).join('')||'<p class="empty">이 분류의 기록이 아직 없습니다.</p>'}</div>${histories.length>vm.historyLimit?`<button class="secondary wide" data-ui="more-history">이전 기록 더 보기 (${histories.length-vm.historyLimit})</button>`:''}<div class="journal-memo"><h3 style="margin-bottom:13px">내가 남기는 메모</h3><div class="notes">${s.notes.map(n=>`<div class="note"><small>${n.age??s.age}세 · 직접 작성 ${!off?`<button class="text-button" data-edit-note="${escape(n.id)}">수정</button>`:''}</small>${escape(n.text)}</div>`).join('')}</div><form id="note-form"><label class="sr-only" for="note-text">생애 메모</label><textarea id="note-text" name="text" maxlength="2000" placeholder="오늘의 선택을 어떤 마음으로 기억하고 싶나요?" ${disabled(off)}></textarea><input type="hidden" name="noteId" value=""><div class="buttons"><button class="secondary" type="submit" ${disabled(off)}>메모 저장</button><button class="text-button" type="button" data-ui="cancel-note">작성 취소</button></div></form>${s.status==='ended'?'<p class="hint" style="margin-top:10px">완료된 삶에도 작별 메모를 남기거나 수정할 수 있습니다. 생애 사건과 결과는 유지됩니다.</p>':''}</div>`; }
function endingStatistics(s) {
 const e=s.ending,stats=e?.stats??{},people=familyRoster(s),value=k=>Number.isFinite(stats[k])?stats[k]:'미기록';
 const descendants=relation=>people.filter(p=>p.relation===relation),grand=descendants('grandchild'),great=descendants('great_grandchild');
 const deadChildren=Number.isFinite(stats.children)&&Number.isFinite(stats.survivingChildren)?stats.children-stats.survivingChildren:'미기록';
 return `<div class="ending-statistics"><h3>삶에 남은 기록</h3><dl>${[['decisions','선택한 결정',value('decisions')],['yearsWorked','유급 근무 연수',value('yearsWorked')],['scholarships','장학 후원 기록',value('scholarships')],['scholarshipGraduates','후원 졸업생',value('scholarshipGraduates')],['children','자녀',value('children')],['survivingChildren','살아 있는 자녀',value('survivingChildren')],['deceasedChildren','먼저 떠난 자녀',deadChildren],['grandchildren','손주',grand.length],['greatGrandchildren','증손',great.length],['countries','거주 국가',value('countries')]].map(([key,label,n])=>`<div><dt>${label}</dt><dd data-ending-stat="${key}">${n}</dd></div>`).join('')}</dl><p class="hint">종료 통계와 저장된 가족 기록을 집계했습니다. 이전 저장에 없는 통계는 미기록으로 표시합니다.</p></div>`;
}
function ending(s) { const e=s.ending;if(!e)return '';return `<section class="ending-panel panel"><div><span class="eyebrow">A LIFE, REMEMBERED</span><h2>${escape(s.name)},<br>${s.age}년의 시간을 남기다.</h2><p>${escape(e.summary??'매일의 선택이 쌓여 하나의 삶이 되었습니다.')}</p><p>${escape(e.cause??'삶의 마침')} · ${s.birthYear}—${s.year}</p><div class="buttons"><button class="primary" data-ui="new-life">또 다른 삶 시작하기 ↗</button><button class="secondary" data-ui="card">회고 카드 저장</button></div></div><div><div class="ending-facts"><div><strong>${s.history.length}</strong><small>기록된 순간</small></div><div><strong>${s.family.children.length}</strong><small>자녀와 이어진 시간</small></div><div><strong>${amount(e.estate??0)}</strong><small>마지막에 남긴 자산</small></div><div><strong>${escape(e.careerSummary?.representativeTitle??s.career.title)}</strong><small>${e.careerSummary?.representativeTitle?"가장 오래 기록된 역할":"마지막에 기록된 역할"}</small></div></div>${endingStatistics(s)}<p class="career-evidence">${e.careerSummary?`기록된 유급 근무 ${e.careerSummary.totalYears}년 · ${e.careerSummary.evidence==='tracked'?'생애 원장 기준':e.careerSummary.evidence==='partial'?'일부 기간만 기록됨':'기록된 역할 없음'}`:'이전 저장에는 경력 원장이 없습니다.'}</p><div class="distribution">${(e.distribution??[]).map(d=>`<div><span>${escape(d.name??d.recipient??d.label??d.target??'상속 대상')}</span><strong>${amount(d.amount??d.value??0)}</strong></div>`).join('')}</div></div></section>`; }

export function dialogShell(title,body) { return `<div class="dialog-header"><h2 id="dialog-title">${escape(title)}</h2><button class="icon-button" data-ui="close-dialog" aria-label="닫기">×</button></div><div class="dialog-body">${body}</div>`; }
export function renderRecords(session,{trashView=false,selectedIds=[],readOnly=false}={}) {
  const current=session.current,complete=session.lives??[],archived=session.archived??[],trash=session.trash??[];
  const active=[...(current?[{s:current,current:true}]:[]),...complete.filter(s=>s.lifeId!==current?.lifeId).map(s=>({s})),...archived.filter(s=>s.lifeId!==current?.lifeId).map(s=>({s,archived:true}))];
  const all=trashView?trash.map(s=>({s,trash:true})):active;
  return dialogShell(trashView?'생애 서재 · 휴지통':'생애 서재',`
    <div class="record-navigation"><button class="${trashView?'secondary':'primary'}" data-ui="records" aria-pressed="${!trashView}">보관한 삶 ${active.length}</button><button class="${trashView?'primary':'secondary'}" data-ui="trash" aria-pressed="${trashView}">휴지통 ${trash.length}</button></div>
    <p>${trashView?'휴지통은 삶의 전체 기록을 보관합니다. 영구 삭제하지 않으며 언제든 복원할 수 있습니다.':`완료된 삶 ${complete.length}개 · 보관한 진행 중 삶 ${archived.length}개. 새 삶을 시작해도 이전 기록은 유지됩니다.`}</p>
    <div class="buttons" style="margin:15px 0 22px"><button class="secondary" data-ui="export">휴지통을 포함한 전체 백업</button><button class="secondary" data-ui="import" ${disabled(readOnly)}>가져오기</button></div>
    ${!trashView&&all.length?`<div class="record-bulk"><label><input id="select-all-records" type="checkbox" data-select-all-records ${selectedIds.length===all.length?'checked':''} ${disabled(readOnly)}> 모든 삶 선택</label><button class="text-button" data-ui="delete-selected" ${disabled(!selectedIds.length||readOnly)}>선택 ${selectedIds.length}개 휴지통으로</button><button class="text-button" data-ui="delete-all" ${disabled(readOnly)}>전체 삶 휴지통으로</button></div>`:''}
    <div class="record-list">${all.map(({s,current,archived,trash})=>`<article class="record-card ${current?'record-current':''}"><header><div><h3>${!trash?`<input id="record-select-${escape(s.lifeId)}" type="checkbox" data-record-select="${escape(s.lifeId)}" aria-label="${escape(s.name)}의 ${s.age}세 기록 선택" ${selectedIds.includes(s.lifeId)?'checked':''} ${disabled(readOnly)}>`:''}${escape(s.name)} <span class="pill">${trash?'휴지통':current?'현재':archived?'진행 중 보관':'완료'}</span></h3><p>${escape(countryName(s.birthCountryId))} → ${escape(countryName(s.countryId))} · ${s.birthYear}—${s.year} · ${s.age}세</p></div>${badge(s.ending?.careerSummary?.representativeTitle??s.career.title)}</header><p>${escape(s.ending?.cause??stage(s.age))}</p><div class="buttons">${trash?`<button class="secondary" data-restore-life="${escape(s.lifeId)}" ${disabled(readOnly)}>이 삶 복원하기</button>`:`<button class="secondary" data-record="${escape(s.lifeId)}" aria-label="${escape(s.name)}의 기록 읽기">기록 읽기</button>${archived?`<button class="secondary" data-resume="${escape(s.lifeId)}" ${disabled(readOnly)}>이 삶 이어하기</button>`:''}<button class="text-button" data-delete-life="${escape(s.lifeId)}" ${disabled(readOnly)}>휴지통으로 이동</button>`}<button class="text-button" data-record-card="${escape(s.lifeId)}" aria-label="${escape(s.name)}의 회고 카드 PNG 저장">회고 카드 PNG</button></div></article>`).join('')||`<div class="empty">${trashView?'휴지통이 비어 있습니다.':'아직 시작한 삶이 없습니다.'}</div>`}</div>
    <p class="hint" style="margin-top:20px">휴지통도 저장 공간을 사용합니다. 서버 공유·공개 추모·결제는 제공하지 않습니다.</p>`);
}
export function renderSettings(session,{busy=false,readOnly=false}={}) {
  const p=session.preferences;
  return dialogShell('환경 설정',`<fieldset class="settings-fieldset" ${disabled(busy||readOnly)}><legend class="sr-only">화면과 소리 설정</legend><div class="settings-grid"><label class="field">화면 테마<select id="theme-preference" data-preference="theme">${options([['light','밝은 종이'],['dark','저녁의 서재']],p.theme)}</select></label><label class="field">인터페이스 언어<select id="locale-preference" data-preference="locale">${options([['ko','한국어'],['en','English · navigation only']],p.locale)}</select><span class="hint">영어는 탐색·주요 조작 이름에 적용됩니다. 이야기와 시스템 설명은 한국어이며, 언어를 바꿔도 저장은 유지됩니다.</span></label>
    <h3>소리와 음악</h3><label class="switch-row"><span>모든 소리 음소거<small>음량 설정을 보존한 채 음악과 조작음을 함께 멈춥니다.</small></span><input id="muted-preference" type="checkbox" data-preference="muted" ${p.muted?'checked':''}></label>
    <label class="switch-row"><span>배경음악<small>외부 음원 없이 직접 합성한 잔잔한 화음입니다.</small></span><input id="music-preference" type="checkbox" data-preference="music" ${p.music?'checked':''}></label>
    <label class="field">배경음악 음량<input id="music-volume" type="range" min="0" max="1" step="0.05" value="${p.musicVolume??.2}" data-preference="musicVolume" aria-valuetext="${Math.round((p.musicVolume??.2)*100)}%"></label><p data-music-status class="hint" aria-live="polite">배경음악 설정을 확인하는 중입니다.</p>
    <label class="switch-row"><span>조작음<small>선택을 저장할 때 짧은 소리를 냅니다. 음악과 별도 설정입니다.</small></span><input id="sound-preference" type="checkbox" data-preference="sound" ${p.sound?'checked':''}></label><label class="field">조작음 음량<input id="sound-volume" type="range" min="0" max="1" step="0.05" value="${p.volume}" data-preference="volume" aria-valuetext="${Math.round(p.volume*100)}%"></label><p class="hint">실제 마우스·키보드 조작 후에만 소리가 시작됩니다. 다른 탭에서는 자동 정지하며 돌아오면 설정에 따라 이어집니다.</p></div>
    ${session.current?.status==='alive'?`<label class="switch-row" style="margin-top:20px"><span>무거운 소재 사건<small>질병 외의 범죄·가정 갈등 등 민감한 이야기 제안</small></span><input id="sensitive-setting" type="checkbox" data-setting="sensitive" ${session.current.settings.sensitive?'checked':''}></label><label class="switch-row" style="margin-top:20px"><span>삶의 마디에서 회고 정지<small>5·15·30·50·70세. 끄면 열린 회고를 닫지만 자동 진행은 다시 시작하지 않습니다.</small></span><input id="reflection-stops-setting" type="checkbox" data-setting="reflectionStops" ${session.current.settings.reflectionStops?'checked':''}></label><label class="field" style="margin-top:20px">현재 삶의 자동 진행 호흡<select id="pacing-setting" data-setting="targetMinutes">${options([['','기본 호흡 · 1년 약 26초'],[30,'30분 호흡 · 1년 약 20초'],[60,'60분 호흡 · 1년 약 40초'],[90,'90분 호흡 · 1년 약 60초']],session.current.settings.targetMinutes??'')}</select><span class="hint">속도 배율이 적용됩니다. 선택·정지·사망 시점에 따라 실제 총 길이는 달라집니다.</span></label>`:''}<div class="scope-badge">게임은 오프라인 규칙으로 실행됩니다. 외부 모델 연결·키·과금 설정은 없습니다.</div></fieldset>`);
}
export function renderHelp() { return dialogShell('이 삶을 읽는 방법',`<h3>선택하고, 한 해를 살아갑니다</h3><p>새 삶은 시간이 흐르는 상태로 시작합니다. 중요한 결정 앞에서는 기다리며, 답을 고르면 원래의 시간 흐름이 이어집니다. 직접 잠시 멈춤을 눌렀다면 답을 고른 뒤에도 멈춘 상태를 유지합니다. 생활 시스템에서는 학업·직업·관계·재정·건강·이동·사회·취미 행동을 선택합니다. 사용할 수 없는 행동에는 필요한 조건을 표시합니다.</p><table class="help-table"><tr><th>다음 해</th><td>한 해의 성장, 일, 지출, 건강과 세계 사건을 계산합니다.</td></tr><tr><th>다음 결정까지</th><td>새로운 결정 또는 삶의 끝에서 멈춥니다.</td></tr><tr><th>자동 진행</th><td>시간 이어가기와 잠시 멈춤으로 조절합니다. 설정·서재·도움말을 열면 잠시 기다리고 닫으면 원래 흐름으로 돌아갑니다. 다른 탭으로 이동하면 안전하게 정지합니다. 결정 자동 응답은 고급 옵션이며 기본은 꺼져 있습니다.</td></tr><tr><th>진행 호흡</th><td>기본 호흡은 한 해 약 26초, 30분 호흡은 한 해 약 20초, 60분 호흡은 한 해 약 40초, 90분 호흡은 약 60초로 자동 진행합니다. 속도 배율·선택·정지·사망 시점 때문에 실제 총 길이는 달라집니다.</td></tr><tr><th>회고 정지</th><td>켜 두면 5·15·30·50·70세에 멈춥니다. 메모와 계속하기는 한 번에 저장하며, 빈 메모로 건너뛸 수도 있습니다. 회고에서는 자동 선택과 자동 진행이 정지됩니다.</td></tr><tr><th>생활 초점</th><td>한 해 동안 마음을 두는 곳입니다. 행동 한 번을 대신하는 자동 AI가 아닙니다.</td></tr><tr><th>반복 지출</th><td>조건과 잔액을 확인하여 실행하며, 자금 부족이면 건너뛰고 기록합니다.</td></tr><tr><th>수동 계획</th><td>직접 적은 목표에 지원 행동을 연결합니다. 단계 실행 때 조건과 비용을 다시 검사합니다.</td></tr></table><h3>독립 규칙과 명시된 가정</h3><p>이 개발 기준판의 문장·화면·수치·확률은 독립 제작입니다. 국가명은 실제 지명입니다. 출생·인구 추첨은 기본 합성 분포 또는 현재 모드에서 선택한 2023 공개 자료를 사용합니다. 국가별 생활 프로필, 직업 급여, 교육·의료 비용, 투자 수익률과 수명은 계속 합성 게임 규칙입니다. 실제 통계·법률·건강 예측이나 원작의 정확한 계산식을 뜻하지 않습니다.</p><p>과거·현재·미래 모드는 각각 1950·2026·2050년에서 시작합니다. 시대 무작위는 이 세 시대 중 하나를 같은 시드로 추첨하며 합성 출생 분포를 사용합니다. 사건이 시간과 선택을 따라 이어지지만 실제 역사나 미래를 모두 재현하지는 않습니다. 비용의 G는 실제 화폐가 아닌 합성 구매력 포인트입니다.</p>${demographicHelp()}<h3>소리와 접근성</h3><p>설정에서 배경음악과 조작음을 각각 켜고 볼륨을 조절합니다. 외부 음원 없이 브라우저에서 만든 짧은 화음이며, 직접 클릭·키 입력 후 재생합니다. 탭을 떠나면 정지하며 전체 음소거도 지원합니다. 운영체제의 동작 줄이기 설정을 따릅니다. 탭 목록은 좌우 방향키·Home·End, 대화상자는 Esc로 탐색·닫을 수 있습니다. 그래프에는 읽을 수 있는 수치 표가 있습니다.</p><h3>데이터와 AI</h3><p>외부 AI는 연결되지 않았습니다. 자유 입력은 메모와 수동 계획으로 보존하고, 실제 효과는 표시된 규칙 행동으로만 실행합니다. 모델이 응답한 것처럼 표시하거나 자연어를 몰래 실행하지 않습니다.</p><p>자동 저장은 이 브라우저의 로컬 저장소를 사용합니다. 창을 닫거나 새로고침해 이어할 수 있습니다. 다른 탭이 저장을 바꾸면 진행을 멈추고 다시 불러오도록 안내합니다. 전체 JSON 내보내기는 휴지통을 포함한 별도 백업입니다. 기록을 목록에서 지우면 휴지통으로 이동하며 확인 창에서 취소하거나 나중에 복원할 수 있습니다. 영구 삭제는 제공하지 않습니다.</p><h3>아직 넘어가지 않은 경계</h3><p>원작의 모든 숨은 분기·정확한 확률·국가별 문화는 검증하지 않았습니다. 공개 커뮤니티와 유료 상품, 서버 동기화, 실제 AI·유료 API는 연결하지 않았습니다. 현재 화면은 최종 제품명·화풍 확정이 아닌 개발용 독립 UI입니다.</p><p>사별·질병·범죄·가정 갈등 등 무거운 소재가 나타날 수 있습니다. 사람을 평가하거나 실제 삶을 예측하는 수치로 읽지 말아 주세요.</p><div class="buttons"><button class="secondary" data-ui="export">내 기록 백업하기</button><button class="primary" data-ui="close-dialog">계속하기</button></div>`); }

export function birthComparison(countryId, comparisonId, basis='synthetic', context={}) {
  if(!comparisonId)return '';
  const {mode='present',birthYear=2026,gender,recorded=true}=context;
  const certificate=context.layout==='certificate';
  const ids=certificate?[comparisonId,countryId==='random'?null:countryId]:[countryId==='random'?null:countryId,comparisonId];
  const refs=ids.map(id=>recorded&&id?getCountryReference(id,mode,birthYear):null);
  const number=(value,digits=1)=>new Intl.NumberFormat('ko-KR',{maximumFractionDigits:digits}).format(value);
  const lifeRows=gender==='female'?[['lifeExpectancyFemale','출생 시 기대수명 · 여성']]:gender==='male'?[['lifeExpectancyMale','출생 시 기대수명 · 남성']]:[['lifeExpectancyFemale','출생 시 기대수명 · 여성'],['lifeExpectancyMale','출생 시 기대수명 · 남성']];
  const rows=[...lifeRows,['underFiveMortality','5세 전 사망 비율'],['expectedSchoolYears','기대 교육 연수'],['gdpPerCapitaPpp','1인당 GDP · PPP']];
  const unavailable=!recorded?'이 삶에는 자료 미기록':mode!=='present'||birthYear!==2026?'이 시대의 자료 미제공':'자료 없음';
  const format=(key,item)=>key==='underFiveMortality'?number(item.value/10)+'%':key==='gdpPerCapitaPpp'?number(item.value,0)+' 국제달러':number(item.value)+'년';
  return `<div class="birth-comparison table-scroll" data-reference-snapshot="${recorded?COUNTRY_REFERENCE_META.id:'unrecorded'}"><table><caption class="${certificate?'sr-only':''}">출생국과 비교국 · 2023 공개 참고 자료</caption><thead><tr><th scope="col">${certificate?'같은 날 태어났다면':'항목'}</th>${ids.map((id,i)=>`<th scope="col">${certificate?(i===0?'비교국<br>':'이 아이의<br>'):''}${id?escape(countryName(id)):i===0?'추첨 뒤 결정':'미선택'}</th>`).join('')}</tr></thead><tbody>${rows.map(([key,label])=>`<tr><th scope="row">${label}</th>${ids.map((id,i)=>{const item=refs[i]?.indicators[key];return `<td data-country-id="${escape(id??'')}" data-reference-indicator="${key}" data-reference-value="${item?.value??''}">${!id?'추첨 뒤 확인':item?.value!=null?format(key,item):key==='expectedSchoolYears'?'미확인':unavailable}</td>`;}).join('')}</tr>`).join('')}</tbody></table><details class="reference-data-note"><summary>자료와 해석</summary><p>세계은행 WDI의 2023년 자료입니다. 기대수명은 출생 시 평균이며 개인의 남은 수명이 아닙니다. 5세 전 사망 비율은 출생아 1,000명당 원자료를 백분율로 표시했습니다. 1인당 GDP(PPP)는 평균 개인소득이나 게임 G의 환산값이 아닙니다. 교육 연수는 검증한 자료가 없습니다.</p><p>현재 모드·2026년 새 출생에만 참고하며, 과거·미래·기존 저장의 빈값을 추정해서 채우지 않습니다. 원작의 자료 집합과 동일하지 않습니다. 생활·사건은 별도 합성 게임 규칙입니다.</p><div class="reference-source-links">${rows.filter(([key])=>COUNTRY_REFERENCE_META.indicators[key]).map(([key,label])=>`<a href="${escape(COUNTRY_REFERENCE_META.indicators[key].sourceUrl)}" target="_blank" rel="noreferrer">${label}</a>`).join(' · ')}</div></details></div>`;
}
function demographicHelp() {
  const coverage=referenceCoverage(COUNTRIES);
  return `<h3>출생 추첨의 공개 자료</h3><p>선택형 공개 자료는 World Bank WDI의 ${DEMOGRAPHIC_META.year}년 인구와 조출생률입니다. 지원하는 ${COUNTRIES.length}개 국가·지역 중 인구 ${coverage.populationCount}개, 출생 가중 ${coverage.birthCount}개를 포함합니다. 자료 없는 ${coverage.missingBirth.length}개 지역은 공개 자료 추첨에서 제외하며 0이나 합성값으로 채우지 않습니다.</p><p>출생 가중치는 인구 × 조출생률 ÷ 1,000으로 계산한 연간 출생 추정값입니다. 직접 관측된 출생수나 원작 추첨 확률이 아닙니다. 공개 자료는 현재 모드의 출생 장소에만 사용하며, 1950년의 역사나 2050년의 예측 자료로 사용하지 않습니다. 생활·건강·소득·학비는 합성 규칙입니다.</p><p><a href="${escape(DEMOGRAPHIC_META.populationUrl)}" target="_blank" rel="noreferrer">WDI 인구 원자료 (새 창)</a> · <a href="${escape(DEMOGRAPHIC_META.birthRateUrl)}" target="_blank" rel="noreferrer">WDI 조출생률 원자료 (새 창)</a><br>자료 연도 ${DEMOGRAPHIC_META.year} · 원천 갱신 ${escape(DEMOGRAPHIC_META.sourceUpdatedAt)} · 취득 ${escape(DEMOGRAPHIC_META.retrievedAt.slice(0,10))} · ${escape(DEMOGRAPHIC_META.license)}</p><details><summary>출생 가중 자료가 없는 국가·지역 ${coverage.missingBirth.length}개</summary><p>${coverage.missingBirth.map(id=>escape(countryName(id))).join(' · ')}</p></details>`;
}
function financeJournal(s,vm) {
  const tl=s.timeline??[],selected=tl.find(x=>x.age===vm.graphAge)??tl.at(-1),index=tl.indexOf(selected);
  const recorded=v=>Number.isFinite(v)?amount(v):'미기록';
  return `<div class="journal-tools"><h3>생활의 경제</h3><span class="hint">G · 합성 구매력 포인트</span></div><div class="chart-legend"><span><i></i>연간 수입</span></div>${renderChart(tl,'income',{label:'나이별 연간 수입',unit:'G'})}<div class="chart-legend"><span><i></i>총순자산 · 금융·주거·임대·사업·차량 포함</span></div>${renderChart(tl,'netWorth',{label:'나이별 총순자산',unit:'G'})}<div class="chart-controls"><button data-graph-delta="-1" aria-label="이전 해의 재정" ${disabled(index<=0)}>←</button><strong>${selected?.age??0}세 · ${selected?.year??s.birthYear}년</strong><button data-graph-delta="1" aria-label="다음 해의 재정" ${disabled(index>=tl.length-1)}>→</button></div>${selected?`<div class="detail-grid">${[['그해 수입 / 지출',`${recorded(selected.income)} / ${recorded(selected.expense)}`],['총순자산',recorded(selected.netWorth)],['현금 / 투자 자산',`${recorded(selected.cash)} / ${recorded(selected.assets)}`],['일반 부채',recorded(selected.debt)],['주택 / 주택 담보',`${recorded(selected.homeValue)} / ${recorded(selected.mortgage)}`],['임대 / 사업 자산',`${recorded(selected.rentalValue)} / ${recorded(selected.businessValue)}`],['차량 가치 / 할부 잔액',`${recorded(selected.carValue)} / ${recorded(selected.carLoan)}`]].map(([title,value])=>`<div class="detail-stat"><small>${title}</small><strong>${value}</strong></div>`).join('')}</div>`:''}<p class="chart-caption">연간 결산 시점의 게임 기록입니다. 총순자산에서 일반 부채·주택 담보·차량 할부를 차감합니다. 이전 저장에 없는 항목은 미기록으로 남기며, 현재 상태로 과거 값을 추정하지 않습니다. 실제 화폐·투자 수익률·세금 제도와 다릅니다.</p>`;
}
function countrySurvivalPanel(s) {
 const c=getCountrySurvivalComparison(s);if(!c)return '<p class="hint">비교할 국가를 선택하면 별도의 합성 환경 생존 비율을 확인할 수 있습니다.</p>';
 const percent=p=>p?Number(p.percent).toFixed(2)+'%':'아직 미도달';
 return `<section class="country-survival" data-country-survival><h3>${escape(c.label)}</h3><p class="hint">${escape(c.explanation)}</p><div class="table-scroll"><table><caption>합성 모형 기대비율 · 동기 5명 표본과 별개</caption><thead><tr><th>국가</th><th>출생</th><th>5세</th><th>${s.status==='ended'?'종료':'현재'} ${s.age}세</th></tr></thead><tbody>${c.series.map(row=>`<tr data-country-id="${row.countryId}"><th scope="row">${escape(row.countryName)}${row.role==='birth'?' · 출생국':''}</th><td>${percent(row.checkpoints.birth)}</td><td>${percent(row.checkpoints.ageFive)}</td><td data-survival-percent="${row.checkpoints.latest.percent}">${percent(row.checkpoints.latest)}</td></tr>`).join('')}</tbody></table></div><details class="country-curves"><summary>합성 두 곡선 보기</summary>${c.series.map(row=>renderChart(row.points,'percent',{label:row.countryName+' · 합성 환경 생존 비율',unit:'%'})).join('')}</details><details><summary>조건과 자체 산식</summary><p>${c.conditions.birthYear}년 · ${c.conditions.city==='urban'?'도시':'농촌'} · ${escape(({low:'빠듯한 살림',middle:'안정된 살림',high:'여유 있는 살림'})[c.conditions.household])}. ${c.conditions.basis==='birth-snapshot'?'저장된 출생 조건을 사용합니다.':'출생 조건 미기록으로 현재 조건을 사용합니다.'}</p><p>${escape(c.model.survival)}</p><p>${escape(c.model.annualDeathRisk)}</p></details></section>`;
}
function comparisonJournal(s,off) {
  const comparison=getCohortComparison(s),basis=s.flags.demographicBasis??'synthetic';
  return `<div class="journal-tools"><h3>같은 순간 시작한 ${comparison.sampleSize}명의 삶</h3><span class="hint">규칙으로 계산한 합성 표본</span></div><div class="cohort-list">${comparison.people.map(p=>{const self=Boolean(p.player),age=p.deathAge??p.age??s.age,alive=p.status!=='ended',last=p.milestones?.at(-1),income=p.finance?.annualIncome??p.finance?.income,health=p.health??p.stats?.health,children=Array.isArray(p.family?.children)?p.family.children.length:p.family?.children;return `<article class="cohort-card"><div class="compare-row ${self?'self':''}"><span><strong>${escape(p.name??'비교 인물')}${self?' · 나':''}</strong><br><small>${escape(countryName(p.countryId))}</small></span><div class="compare-bar" aria-hidden="true"><span style="width:${Math.min(100,Math.max(0,age)/110*100)}%"></span></div><span>${age}세<br><small>${p.projected?'후속 모의 결과':alive?'살아가는 중':'삶의 마침'}</small></span></div><p>${escape(EDUCATION[p.education?.level]??'학력 미기록')} · ${escape(p.career?.title??'경력 미기록')} · 건강 ${Number.isFinite(health)?Math.round(health):'미기록'} · 자녀 ${children??'미기록'}명</p><p>출생 장소 자료: ${self?(basis==='reference-2023'?'2023 WDI 공개 분포':'합성 게임 분포'):p.demographicSource==='worldbank-wdi-2023'?'2023 WDI 공개 분포':p.demographicSource==='synthetic-population-birth-v2'?'합성 게임 분포':'이전 저장 · 개별 출처 미기록'}</p><p>연간 수입 ${Number.isFinite(income)?amount(income):'미기록'}${last?` · ${last.age}세: ${escape(last.text)}`:''}</p></article>`;}).join('')}</div><h3 style="margin-top:28px">이 표본의 생존 비율</h3>${renderChart(comparison.survival,'value',{label:`합성 ${comparison.sampleSize}명 표본의 나이별 생존 비율`,unit:'%'})}<p class="chart-caption">나와 비교 인물 ${comparison.sampleSize-1}명의 게임 상태를 집계한 작은 합성 표본입니다. 국가 생존 통계나 개인의 미래 예측이 아닙니다. ${comparison.projected?'완료된 삶의 비교에서는 남아 있던 인물의 이후 시간을 독립 규칙으로 모의 실행했습니다. 후속 모의 결과는 관찰된 과거와 구분합니다.':'아직 살아 있는 인물의 미래 수명은 미정이며 현재 관찰 나이까지만 표시합니다.'}</p><p class="scope-badge">이 삶의 출생 추첨 자료: ${basis==='reference-2023'?'2023 WDI 공개 인구·출생률':'합성 게임 분포'}. 나와 비교 인물의 생활·사건은 합성 규칙입니다.</p><label class="field" style="max-width:300px;margin-top:20px">비교할 국가<select data-setting="comparisonCountry" ${disabled(off)}><option value="">비교하지 않음</option>${countryOptions(s.settings.comparisonCountry,false)}</select></label>${birthComparison(s.birthCountryId,s.settings.comparisonCountry,basis,{mode:s.mode,birthYear:s.birthYear,gender:s.gender,recorded:s.flags.countryReferenceSnapshot===COUNTRY_REFERENCE_META.id})}${countrySurvivalPanel(s)}`;
}

function communityDetails(s) {
  const campaign=s.flags.politicalCampaign,service=s.flags.politicalServiceYears,students=s.flags.scholarshipStudents??[];
  const status={preparing:'정치 활동 준비 중',pending:'공천 심사 중',approved:'공천 승인 · 선거 출마 가능',rejected:'공천 심사 탈락',cancelled:'준비·심사 취소',elected:'선거 당선',defeated:'선거 낙선',interrupted:'준비·심사 중단'};
  const level={local:'지방',national:'국가'};
  const row=(label,value)=>`<div class="detail-stat"><small>${escape(label)}</small><strong>${escape(value)}</strong></div>`;
  return `<div class="detail-grid">${row('현재 공직',s.politics.role?(level[s.politics.role]??s.politics.role)+' 대표':'직책 없음')}${row('남은 임기',s.politics.term+'년')}${row('정치 준비 단계',campaign?(status[campaign.status]??'상태 미확인'):'아직 준비하지 않음')}${row('도전하는 선거',campaign?(level[campaign.level]??'미기록')+' 대표':'미선택')}${row('기록된 공직 활동',service?'지방 '+(service.local??0)+'년 · 국가 '+(service.national??0)+'년':'아직 기록 없음')}${row('현재 장학 후원',s.finance.scholarships+'명')}</div>${campaign?`<p class="hint">내 ${campaign.startedAge}세에 준비 시작${Number.isFinite(campaign.appliedAge)?' · '+campaign.appliedAge+'세에 공천 신청':''}${Number.isFinite(campaign.resolvedAge)?' · '+campaign.resolvedAge+'세에 심사·선거 결과 기록':''}. 공천 심사와 선거 결과는 합성 게임 규칙입니다.</p>`:''}<h4 class="detail-subheading">후원 학생의 이후 이야기</h4><div class="scholarship-list">${students.map((student,index)=>`<article class="scholarship-card"><strong>후원 학생 ${index+1}</strong><span class="pill">${student.graduated?'졸업':student.stopped?'후원 종료':'학업·후원 진행 중'}</span><p>실제 후원 ${student.years}년${Number.isFinite(student.graduatedAge)?' · 내 '+student.graduatedAge+'세에 졸업':''}</p><p>진로: ${student.careerId?escape(({teacher:'교사',nurse:'간호사',electrician:'전기 기술자'})[student.careerId]??student.careerId):student.graduated?'졸업 이후 소식을 기다리는 중':'졸업 전 · 아직 정해지지 않음'}${Number.isFinite(student.careerNotifiedAge)?' · 내 '+student.careerNotifiedAge+'세에 소식 확인':''}</p></article>`).join('')||'<p class="hint">아직 후원 학생 기록이 없습니다.</p>'}</div><p class="hint">학생과 진로, 비용은 합성 게임 기록이며 실제 사람이나 후원 사업과 연결되지 않습니다.</p>`;
}

function reflectionDecision(s,vm) {
  const off=vm.busy||vm.readOnly||vm.viewing,view=getReflectionView(s);
  if(!view)return '<p>이 회고의 현재 기록을 불러올 수 없습니다.</p>';
  const refs=[view.statistics.birth,view.statistics.comparison].filter(Boolean);
  const birth=view.statistics.birth,comparison=view.statistics.comparison,percent=value=>new Intl.NumberFormat('ko-KR',{maximumFractionDigits:2}).format(value);
  const intro=view.age===5&&birth.underFiveMortalityPercent!=null
    ? birth.countryName+'의 '+birth.referenceYear+'년 5세 전 사망 비율은 '+percent(birth.underFiveMortalityPercent)+'%입니다. '+(comparison?.underFiveMortalityPercent!=null?'비교국 '+comparison.countryName+'은 '+percent(comparison.underFiveMortalityPercent)+'%입니다. ':comparison?comparison.summary+' ':'')+'이 삶은 다섯 살을 맞았습니다.'
    : view.intro;
  const shortCohort=summary=>summary.replace('정규 학교 과정을 시작하기 전입니다.','취학 전').replace('기록된 학업 과정을 이어 가고 있습니다.','학업 중').replace(' 교육을 이어 가고 있습니다.',' 교육 중').replace(' 일을 하고 있습니다.',' 근무 중').replace('현재 직업은 기록되어 있지 않습니다.','현재 직업 미기록');
  return `<div class="reflection-content" data-reflection-age="${view.age}" data-question-source="${escape(view.questionSource)}"><h2 id="decision-title" tabindex="-1">${escape(view.title)}</h2><p class="reflection-intro">${escape(intro)}</p><div class="reflection-cohort" aria-label="동기의 현재 근황"><span>동기 근황 — </span>${view.cohort.length?view.cohort.map(p=>`<span data-reflection-person="${escape(p.id)}" title="${escape(p.summary)}">${escape(p.name)}(${escape(p.countryName)}): ${escape(shortCohort(p.summary))}</span>`).join(' · '):escape(view.cohortSummary)}</div><form id="reflection-form" class="reflection-form"><label for="reflection-text">${escape(view.question)}</label><textarea id="reflection-text" name="text" maxlength="2000" placeholder="${escape(view.placeholder)} (적지 않아도 괜찮아요)" ${disabled(off)}></textarea><div class="choices"><button type="submit" class="choice" ${disabled(off)}><span class="choice-number">1</span><span class="choice-content"><strong>적어 두고 계속</strong><small>남긴 글은 이 삶의 메모에 저장됩니다.</small></span></button><button type="button" class="choice" data-ui="skip-reflection" ${disabled(off)}><span class="choice-number">2</span><span class="choice-content"><strong>그냥 계속</strong></span></button></div></form><div class="reflection-options"><button class="small-button auto-offer" data-ui="toggle-auto" ${disabled(off)}>이제부터 결정을 자동으로 맡기기</button><button class="small-button auto-offer" data-ui="toggle-reflection" ${disabled(off)}>다음부터 회고 창 띄우지 않기</button></div><details class="reflection-sources"><summary>자료와 질문의 출처</summary>${view.limitations.map(text=>`<p>${escape(text)}</p>`).join('')}${refs.map(ref=>`<p data-reflection-country="${escape(ref.countryId)}" data-reference-status="${escape(ref.status)}">${escape(ref.summary)} ${safeReferenceURL(ref.indicators?.underFiveMortality?.sourceUrl)?`<a href="${escape(safeReferenceURL(ref.indicators.underFiveMortality.sourceUrl))}" target="_blank" rel="noreferrer">세계은행 원자료</a>`:''}</p>`).join('')}<p>${view.questionSource==='observed_adaptation'?'5세 질문은 확인한 원작의 질문 맥락을 바탕으로 자체 작성했습니다.':'이 나이의 질문은 자체 작성했습니다.'}</p></details></div>`;
}

function isMilestoneReflection(s) {return s.pending?.kind==='reflection'&&s.pending.structure?.startsWith('milestone-reflection:');}
function flowControls(s,vm,l) {
  const off=vm.busy||vm.readOnly||vm.viewing||s.status==='ended',reflection=isMilestoneReflection(s),waiting=Boolean(s.pending);
  const status=s.status==='ended'?'이 삶은 마지막에 도착했습니다.':reflection?'회고를 위해 멈췄습니다.':vm.readOnly?'저장을 보호하기 위해 멈췄습니다.':vm.viewing?'보관된 삶을 읽는 중입니다.':waiting?(vm.playing?'선택을 기다립니다. 답하면 시간이 이어집니다.':vm.pauseReason==='reloaded'?'저장된 결정을 불러왔습니다. 안전 복귀로 시간을 멈췄습니다.':'선택을 기다립니다. 시간은 멈춰 있습니다.'):vm.playing?'시간이 흐르는 중':vm.pauseReason==='reloaded'?'저장된 삶을 불러왔습니다. 안전 복귀 후 시간 이어가기를 눌러 주세요.':vm.pauseReason==='hidden'?'다른 탭으로 이동하여 멈췄습니다. 준비되면 이어가세요.':vm.pauseReason==='error'||vm.pauseReason==='conflict'?'저장 상태를 확인할 때까지 멈췄습니다.':'시간을 잠시 멈췄습니다.';
  return `<div class="flow-status" data-flow-state="${waiting?'waiting':vm.playing?'running':'paused'}"><span class="flow-dot" aria-hidden="true"></span><span>${status}</span><span id="flow-clock" aria-live="off"></span><span class="flow-progress" aria-hidden="true"><i id="flow-progress"></i></span></div><div class="turn-controls"><button class="primary flow-play" data-ui="play" aria-pressed="${vm.playing}" aria-label="${vm.playing?'시간 흐름 잠시 멈추기':'시간 흐름 이어가기'}" ${disabled(off||reflection)}>${vm.playing?'Ⅱ 잠시 멈춤':'▷ 시간 이어가기'}</button><button class="secondary" data-command="advance" ${disabled(off||waiting)}>${tr(l,'한 해 바로 보기','Next year')} →</button><button class="text-button" data-command="nextDecision" ${disabled(off||waiting)}>${tr(l,'다음 결정까지','Next decision')}</button><label class="sr-only" for="speed">진행 속도</label><select id="speed" data-setting="speed" ${disabled(off)}>${options([[.5,'0.5배'],[1,'1배'],[2,'2배'],[4,'4배'],[8,'8배'],[12,'12배'],[16,'16배']],s.settings.speed)}</select></div>`;
}
function compactLifeSummary(s) {
  return `<section class="compact-life panel" aria-label="현재 삶 요약">${portrait(s)}<div class="compact-identity"><strong>${escape(s.name)} · ${s.age}세</strong><span>${s.year}년 · ${escape(countryName(s.countryId))} · ${escape(stage(s.age))}</span></div><div class="compact-numbers"><span>건강 <b>${Math.round(s.stats.health)}</b></span><span>행복 <b>${Math.round(s.stats.happiness)}</b></span><span>생활 자금 <b>${amount(s.finance.cash)}</b></span></div></section>`;
}
function recentLifeFeed(s) {
  const recent=s.history.slice(-6).reverse(),timeline=s.timeline??[],latest=timeline.at(-1),previous=timeline.length>1?timeline.at(-2):null;
  const change=(key,label)=>{if(!latest||!previous||!Number.isFinite(latest[key])||!Number.isFinite(previous[key]))return '';const value=Math.round((latest[key]-previous[key])*10)/10;return `<span>${label} ${value>0?'+':''}${value}</span>`;};
  const daily=s.flags.educationOnLeave?'학업을 잠시 쉬는 중 · 과정과 남은 기간은 보관됩니다.':s.flags.educationPaused?'학비가 부족해 수강이 보류되어 있습니다. 다음 방향을 고를 수 있습니다.':s.education.program?`${s.education.program.label}에서 배우는 중 · 남은 학업 ${s.education.yearsLeft}년`:s.career.jobId?`${s.career.title}로 지내는 중 · 경력 ${s.career.years}년`:s.career.retired?'일의 속도를 늦추고 생활을 이어가는 중':s.age<6?'작은 변화가 쌓이며 자라는 시기':s.age<18?'배움과 관계 속에서 자라는 시기':'일상과 관계, 다음 방향을 만들어 가는 중';
  return `<section class="recent-life panel" aria-labelledby="recent-life-title"><header><div><span class="eyebrow">THE STORY CONTINUES</span><h3 id="recent-life-title">${s.year}년, ${s.age}세의 하루</h3></div><span class="pill">${escape(countryName(s.countryId))}</span></header><p class="daily-context">${escape(daily)}</p><div class="year-feedback"><span>연간 수입 ${amount(s.finance.annualIncome)}</span>${change('health','건강')}${change('happiness','행복')}${previous?'<small>건강·행복은 이전 연도 기록 대비</small>':''}</div><ol class="recent-events">${recent.map(h=>`<li><span class="event-time">${h.age}세 · ${h.year}</span><div><h4>${escape(h.title)}</h4><p>${escape(h.text)}</p></div></li>`).join('')||'<li>아직 기록된 사건이 없습니다.</li>'}</ol><button class="text-button" data-journal="chronicle">이전 이야기와 메모 펼치기 →</button></section>`;
}

// Rendered-reference layout, observed 2026-10-14. Artwork and game rules are local.
export const yearDurationMs = settings => Math.max(350, (({30:20000,60:40000,90:60000})[settings.targetMinutes] ?? 26000)/(settings.speed || 1));
export const paceSeconds = s => new Intl.NumberFormat('ko-KR', { maximumFractionDigits: 1 }).format(yearDurationMs(s.settings)/1000);
export function portrait(s) { return `<img class="pixel-portrait" width="128" height="160" src="${portraitDataURL(s)}" alt="${escape(s.name)}의 독자 제작 픽셀 초상">`; }
export function scene(s={age:0,seed:4,city:'urban',household:'middle',status:'alive'}) { return `<img class="pixel-scene" width="192" height="60" src="${sceneDataURL(s)}" alt="${escape(describeScene(s).label)}">`; }
function segmented(name,entries,value) { return `<div class="segmented">${entries.map(([v,label])=>`<label><input type="radio" name="${name}" value="${v}" ${String(v)===String(value)?'checked':''}><span>${label}</span></label>`).join('')}</div>`; }
function localExamples() { return [{name:'서윤의 이야기',countryId:'KR',age:76,seed:11,city:'urban',household:'middle',status:'alive'},{name:'민준의 이야기',countryId:'KR',age:65,seed:22,city:'rural',household:'low',status:'alive'},{name:'하린의 이야기',countryId:'KR',age:82,seed:33,city:'urban',household:'high',status:'alive'}]; }
function memoryCards(session,mini=false) { const items=session.lives.length?session.lives.slice(-5).reverse():localExamples();return `<div class="memory-row ${mini?'mini':''}">${items.map(s=>`<button class="memory-card" ${s.lifeId?`data-record="${escape(s.lifeId)}"`:'data-ui="local-examples"'}>${scene(s)}<span><strong>${escape(s.name)}</strong><small>${s.lifeId?`${s.birthYear}–${s.year} · ${escape(countryName(s.countryId))}`:'가상 로컬 예시'}</small>${mini?'':`<b>${s.lifeId?`${s.age}년 동안 쌓인 선택과 기억`:'이 화면의 구성을 보여 주는 예시입니다.'}</b>`}</span></button>`).join('')}</div>`; }
function worldDiagram(id='landing-world',countryId=null) { return `<img id="${id}" class="world-diagram" width="640" height="271" src="${worldMapDataURL(countryId)}" alt="자체 제작 대륙권 도식">`; }
function distributionCard() { const rows=referenceDistribution(COUNTRIES,'birth').map(r=>({...r,id:r.countryId})),top=rows.sort((a,b)=>b.share-a.share).slice(0,9);return `<section class="distribution-card panel"><h2>지금 태어나는 아기라면</h2><p class="hint">현재 모드 2023 참고분포 · WDI · 215/249 국가·지역</p><div class="birth-bars">${top.map(c=>`<div data-country-id="${escape(c.id)}" data-share="${c.share}"><span title="${escape(countryName(c.id))}">${escape(countryName(c.id))}</span><i><b style="width:${c.share/top[0].share*100}%"></b></i><span>${(c.share*100).toFixed(1)}%</span></div>`).join('')}<div><span>그 밖의 국가·지역</span><i><b style="width:100%;opacity:.5"></b></i><span>${(100-top.reduce((n,c)=>n+c.share*100,0)).toFixed(1)}%</span></div></div><button class="small-button" data-ui="help">추첨 자료와 규칙 보기</button></section>`; }
export function renderStart(session,{busy=false,readOnly=false,panels={}}={}) {
 const off=busy||readOnly;
 return `<section class="reference-start" data-stage="start"><nav class="landing-languages" aria-label="화면 설정"><button data-ui="settings">English</button><button class="selected" data-ui="settings">한국어</button><button data-ui="theme" aria-label="화면 밝기 바꾸기">◐</button></nav><div class="reference-wrap"><section class="landing-hero"><div class="hero-copy"><p class="hero-kicker">비공식 로컬 재현 · 개발 기준판 · 독립 규칙</p><h1>80억<br> 분의 <em>1</em></h1><p class="hero-description">어디에서 태어날지는 고를 수 없지만,<br>그다음의 삶에는 당신의 선택이 남습니다.<br>한 사람의 시작부터 마지막까지 살아 보세요.</p><div class="landing-counters"><div><b>${session.lives.length}</b><span>이 브라우저의 완료된 삶</span></div><div><b>${session.archived.length}</b><span>다시 이어갈 수 있는 삶</span></div></div><p class="local-presence">● 이 기기에 기록됩니다. 공개 서비스와 연결되지 않았어요.</p><div class="mini-memory-heading"><span>간직한 삶</span><button data-ui="records">모두 보기</button></div>${memoryCards(session,true)}</div><div class="hero-aside">${worldDiagram()}${distributionCard()}</div></section><section class="local-community"><h2>함께 나눈 삶</h2><p>가상 로컬 예시입니다. 공개 공유·댓글·추모는 연결되지 않았습니다.</p><div class="community-grid">${localExamples().map((s,i)=>`<article><h3>${escape(s.name)} <small>가상 인물 · ${s.age}세</small></h3><p>${['배움과 일을 오가며 가족과 시간을 쌓은 삶.','익숙한 마을에서 사람들과 함께한 삶.','새로운 도시에서 취미와 친구를 만난 삶.'][i]}</p><blockquote>“${['오래 기억하고 싶은 작은 순간들이 있어요.','평범한 하루에도 이야기는 남습니다.','마지막까지 곁에 있는 사람을 떠올려요.'][i]}”</blockquote><button class="remember-button" data-ui="local-examples">로컬 예시 안내</button></article>`).join('')}</div><button class="secondary" data-ui="records">내 기록 모두 보기</button></section><form id="birth-form"><fieldset ${disabled(off)}><legend class="sr-only">새 삶 설정</legend><div class="birth-options"><div><label class="option-label">태어날 세상</label>${segmented('mode',[['past','지난 세상'],['present','지금 세상'],['future','다가올 세상'],['random','아무 세상이나']],'present')}<p class="hint">과거·현재·미래의 합성 세계에서 시작합니다.</p></div><div><label class="option-label">나라를 뽑는 기준</label>${segmented('weighting',[['birth','지금 태어나는 아기'],['population','지금 사는 인구']],'birth')}<p class="hint">출생 또는 인구 비중으로 고릅니다. 어느 쪽이든 삶은 0세에서 시작합니다.</p></div><div><label class="option-label">한 번의 인생 길이</label>${segmented('targetMinutes',[[30,'약 30분'],[60,'약 1시간'],[90,'약 1시간 30분']],60)}<p class="hint">자체 호흡: 1년 약 20·40·60초. 선택·정지·생애 길이에 따라 실제 시간은 달라집니다.</p></div><label class="field comparison-field">당신이 실제로 태어난 나라 (선택)<select name="comparisonCountry"><option value="">고르지 않을래요</option>${countryOptions('KR',false)}</select><span class="hint">선택은 이 기기에 보관합니다. 해당 시대의 공개 참고 자료와 게임 속 삶을 구분해 비교합니다.</span></label></div><details id="birth-advanced" class="birth-advanced" data-panel="startadvanced" ${panels.startadvanced?'open':''}><summary>이름·출생 환경·자료 직접 설정</summary><div class="form-grid"><label class="field">이름<input name="name" maxlength="40" placeholder="비워 두면 무작위 이름" autocomplete="off"></label><label class="field">성별<select name="gender">${options([['random','무작위'],['female','여성'],['male','남성'],['nonbinary','논바이너리']],'random')}</select></label><label class="field full">추첨 자료<select name="demographicBasis">${options([['synthetic','합성 게임 분포'],['reference-2023','2023 공개 인구·출생률 자료 · 현재 모드']],'reference-2023')}</select><span class="hint" id="birth-data-info"></span></label><label class="field full">태어날 곳<select name="countryId">${countryOptions()}</select><span class="hint" id="birth-country-info"></span></label><label class="field">가정 형편<select name="household">${options([['random','무작위'],['low','빠듯한 살림'],['middle','안정된 살림'],['high','여유 있는 살림']],'random')}</select></label><label class="field">생활 환경<select name="city">${options([['random','무작위'],['urban','도시'],['rural','농촌']],'random')}</select></label><label class="field full">시드 (선택)<input name="seed" type="number" min="0" max="4294967295" step="1" placeholder="같은 출생 설정과 선택으로 재현"></label><label class="switch-row full"><span>삶의 마디에서 회고<small>5·15·30·50·70세에 멈추고 메모를 남깁니다.</small></span><input name="reflectionStops" type="checkbox" checked></label><div class="full" id="birth-comparison"></div></div></details><div class="start-cta-row"><button class="primary start-button" type="submit">태어나기</button><span class="hint">설정은 그대로 두고 바로 태어나도 괜찮아요.</span><button class="secondary" type="button" data-ui="music">♪ 잔잔한 음악</button>${session.current?'<button class="secondary" type="button" data-ui="continue">현재 삶 계속하기</button>':''}</div><p class="hint">질병·사별 등 무거운 사건이 나타날 수 있습니다. 생활과 사건은 합성 게임 규칙입니다.</p></fieldset></form><section class="memorial-section"><h2>추모관</h2><p>이 브라우저에서 끝까지 살아 낸 삶을 간직합니다. 처음에는 가상 로컬 예시를 보여 줍니다.</p>${memoryCards(session)}<div class="buttons"><button class="secondary" data-ui="records">추모관 둘러보기</button><button class="secondary" data-ui="records">전생의 집</button><button class="secondary" data-ui="import">기록 가져오기</button></div></section><section class="landing-explanation"><article><h3>같은 시작, 다른 삶</h3><p>네 명의 동기와 함께 태어납니다. 선택과 환경에 따라 각자의 이야기가 이어집니다. 이들의 생활과 사건은 합성 규칙입니다.</p></article><article><h3>잠시 멈춤</h3><p>다섯, 열다섯, 서른, 쉰, 일흔 살에 지나온 시간을 돌아봅니다. 원하는 한 줄을 남기거나 마음속에 담고 계속할 수 있어요.</p></article><article><h3>어떤 자료를 쓰나요?</h3><p>현재 모드의 새 출생은 WDI 2023 공개 인구·조출생률 자료를 기본으로 씁니다 (215/249 국가·지역). 원작의 UN 자료·172개 범위와 다릅니다. 출생 비교의 기대수명·아동 사망·GDP PPP도 2023 공개 참고값입니다. 실제 게임의 생활·소득·수명과 과거·미래는 합성 규칙입니다.</p></article></section><div class="landing-footer"><p>비공식 로컬 재현입니다. 원작의 구성 관찰을 바탕으로 자체 코드와 그림을 사용했습니다.</p><div class="buttons"><button class="secondary" data-ui="settings">설정</button><button class="secondary" data-ui="help">규칙·자료 안내</button><button class="secondary" data-ui="records">기록 관리</button></div></div></div><div class="floating-start"><button class="primary" type="submit" form="birth-form" ${disabled(off)}>태어나기</button></div></section>`;
}
export function renderBirthCertificate(s,session,vm) {
 const identity=getBirthIdentity(s),birthPlace=identity?.cityLabel??((s.flags.birthSnapshot?.city??s.city)==='urban'?'도시':'농촌'),stats=birthReferenceFacts(s);
 const parent=(p,i,job=false)=>{const b=getPersonBirthContext(s,p.id),role=b?.role==='mother'?'어머니':b?.role==='father'?'아버지':'부모 '+(i+1);return role+' '+(b?.presentAtBirth===false?'부재':job?b?.occupationLabel??'미기록':p.age+'세');};
 const info=[['성별',({female:'여성',male:'남성',nonbinary:'논바이너리'})[s.gender]??s.gender],['출생국',countryName(s.birthCountryId)],['출생지',birthPlace],['가정 형편',({low:'빠듯한 살림',middle:'안정된 살림',high:'여유 있는 살림'})[s.household]],['부모 나이',s.family.parents.map((p,i)=>parent(p,i)).join(' · ')],['부모님 일',s.family.parents.map((p,i)=>parent(p,i,true)).join(' · ')],['부모님 집',HOME[s.finance.home]??s.finance.home],['종교','미기록'],['기대수명',stats.expectancy],['5세 전 사망 비율',stats.mortality],['1인당 GDP (PPP)',stats.gdp]];
 const sources='<details class="certificate-source-note"><summary>출생 설정·자료 안내</summary><p>'+escape(IDENTITY_META.note)+'</p><p>종교·민족은 미기록입니다. 생활·사건은 독립적인 합성 규칙입니다. 지도는 현대 국가·지역의 표기 위치이며 정확한 출생 좌표가 아닙니다. 공개 통계는 2023 참고값이며 게임 결과를 예측하지 않습니다.</p>'+(identity&&safeReferenceURL(identity.citySource)?'<a href="'+escape(safeReferenceURL(identity.citySource))+'" target="_blank" rel="noreferrer">지명 자료</a>':'')+'</details>';
 return '<section class="certificate-wrap" data-stage="birth-certificate"><article class="birth-certificate panel"><header><h2>출생 신고</h2><span>No. '+escape(s.lifeId.slice(-16))+'</span></header><div class="certificate-body">'+renderBirthOrnament()+'<small>이름</small><h1>'+escape(s.name)+'</h1><p class="certificate-intro">'+s.birthYear+'년'+(identity?.birthMonth?' '+identity.birthMonth+'월':'')+', '+escape(countryName(s.birthCountryId))+'의 '+escape(birthPlace)+'에서 태어났습니다. '+escape(({low:'빠듯한',middle:'안정된',high:'여유 있는'})[s.household])+' 살림 속에서 이야기가 시작됩니다.'+(Number.isInteger(identity?.siblings)?' 위 형제자매는 '+identity.siblings+'명입니다.':'')+'</p><p class="hint">삶을 시작하면 시간이 흐릅니다 (1년 ≈ '+paceSeconds(s)+'초). 이 브라우저에 저장되어 다시 이어할 수 있어요.</p><div class="certificate-facts">'+info.map(([label,value])=>'<div><small>'+label+'</small><strong>'+escape(value)+'</strong></div>').join('')+'</div>'+renderBirthMap(s)+renderBirthShare(s)+birthComparison(s.birthCountryId,s.settings.comparisonCountry,s.flags.demographicBasis??'synthetic',{mode:s.mode,birthYear:s.birthYear,gender:s.gender,recorded:stats.recorded,layout:'certificate'})+'<section class="certificate-cohort"><p class="hint">같은 시작을 맞은 사람들</p>'+getCohortComparison(s).people.filter(p=>!p.player).map(p=>'<div><strong>'+escape(p.name)+'</strong><span>'+escape(countryName(p.countryId))+' · 합성 생애</span></div>').join('')+'<p class="hint">이들의 삶도 독립 규칙으로 흘러갑니다. 곁에서 함께 보여 드릴게요.</p></section>'+sources+'<div class="certificate-actions"><button class="secondary" data-ui="card">출생 카드 공유</button><button class="primary" data-ui="begin-life" '+disabled(vm.busy||vm.readOnly)+'>삶을 시작하기</button></div></div></article></section>';
}

function lifeIdentity(s) { const identity=getBirthIdentity(s);return `<section class="identity-card panel"><header><span>신원 기록 · ${escape(s.birthCountryId)}</span><span>${s.birthYear}</span></header><div class="identity-body">${portrait(s)}<div><h2>${escape(s.name)}</h2><dl><dt>성별</dt><dd>${escape(({female:'여성',male:'남성',nonbinary:'논바이너리'})[s.gender]??s.gender)}</dd><dt>출생</dt><dd>${escape(countryName(s.birthCountryId))} · ${s.birthYear}년${identity?.birthMonth?' '+identity.birthMonth+'월':''}</dd><dt>거주</dt><dd>${escape(getResidenceLabel(s))}, ${escape(countryName(s.countryId))}</dd><dt>종교·민족</dt><dd>미기록</dd><dt>출신 가정</dt><dd>${escape(({low:'●○○ 빠듯한 살림',middle:'●●○ 안정된 살림',high:'●●● 여유 있는 살림'})[s.household])}</dd><dt>학력</dt><dd>${escape(EDUCATION[s.education.level]??s.education.level)}${s.education.program?` (${escape(s.education.program.label)} ${s.flags.educationOnLeave?'휴학':s.flags.educationPaused?'수강 보류':'재학'})`:''}</dd><dt>직업</dt><dd>${escape(s.career.title)}</dd></dl></div></div><div class="identity-code">I&lt;${escape(s.birthCountryId)}${escape(s.name.toUpperCase())}&lt;&lt;&lt;&lt;&lt;&lt;&lt;&lt;&lt;&lt;&lt;<br>${s.birthYear}${identity?.birthMonth?String(identity.birthMonth).padStart(2,'0'):'??'}&lt;${escape(s.gender.slice(0,1).toUpperCase())}${escape(s.birthCountryId)}&lt;${String(s.age).padStart(3,'0')}&lt;&lt;&lt;&lt;&lt;&lt;&lt;&lt;&lt;&lt;&lt;</div></section>`; }
function focusEntries(s) { return focusOptions(s); }
function mobileFocusPicker(s,vm) {
 if(!vm.focusPickerOpen||s.age<6)return '';
 const off=vm.busy||vm.readOnly||vm.viewing||s.status==='ended',entries=focusEntries(s);
 return '<div id="mobile-focus-picker" class="mini-focus-picker focus-chips" role="group" aria-label="올해의 초점 빠른 선택">'+entries.map(([id,label,effect])=>'<button type="button" id="mobile-focus-'+id+'" data-focus="'+id+'" aria-pressed="'+(s.focus===id)+'" '+disabled(off)+'><span>'+escape(label)+'</span><small>'+escape(effect)+'</small></button>').join('')+'</div>';
}
function baseStats(s,mini=false,vm={}) { return `<section class="${mini?'mobile-minibar':'reference-stats panel'}" aria-label="현재 상태">${mini?'':'<div class="panel-heading"><h2>상태</h2><small>0–100</small></div>'}<div class="${mini?'mini-stat-list':'reference-stat-list'}">${[['health','건강'],['happiness','행복'],['knowledge','지식'],['social','관계']].map(([k,label])=>`<div class="reference-stat ${k}"><span>${label}</span><i><b style="width:${Math.round(s.stats[k])}%"></b></i><strong>${Math.round(s.stats[k])}</strong></div>`).join('')}</div>${mini?`${s.age>=6?`<button type="button" id="mobile-focus-trigger" data-ui="focus-picker" class="mini-focus" aria-controls="mobile-focus-picker" aria-expanded="${!!vm.focusPickerOpen}" aria-label="현재 초점 ${escape(focusLabel(s))}, 초점 선택 열기">${escape(focusLabel(s))} ▾</button>`:''}<button data-ui="finance">돈 쓰기</button>${mobileFocusPicker(s,vm)}`:`<details class="stat-help"><summary>상태는 무엇을 뜻하나요?</summary><p>이 값들은 게임 규칙의 0–100 지표입니다. 활력 ${Math.round(s.stats.energy)}. 실제 건강·능력을 진단하지 않습니다.</p></details><div class="reference-money"><div><small>순자산 (게임 G)</small><strong data-net-worth="${netWorth(s)}">${amount(netWorth(s))}</strong><span>${escape(HOME[s.finance.home]??s.finance.home)}</span></div><div><small>연 소득 (게임 G)</small><strong>${amount(s.finance.annualIncome)}</strong><span>연 지출 ${amount(s.finance.annualExpense)}</span></div></div><button class="text-button money-link" data-ui="finance">돈 쓰기 · 투자 열기</button>`}</section>`; }
function netWorth(s) { const f=s.finance;return f.cash+f.assets+(f.homeValue??0)+(s.flags.rentalValue??0)+(f.business?.level??0)*1000+(s.flags.carValue??0)-f.debt-(f.mortgage??0)-(s.flags.carLoan??0); }
function referenceFocus(s,vm) { const off=vm.busy||vm.readOnly||vm.viewing||s.status==='ended',focuses=focusEntries(s);return `<section class="reference-focus panel" id="year-focus"><div class="panel-heading"><h2>올해의 초점</h2>${s.age>=6?'<small>언제든 바꿀 수 있어요</small>':''}</div><p class="hint">${escape(focusStageLabel(s))} · ${escape(getResidenceLabel(s))} · ${escape(countryName(s.countryId))}</p>${s.age<6?'<p>아직 아기입니다. 부모님이 키우는 중이에요. 작은 경험이 쌓이고, 여섯 살부터 한 해의 초점을 고를 수 있습니다. 이 시기는 배속을 높여 보아도 좋습니다.</p>':`<div class="focus-chips">${focuses.map(([id,label,effect])=>`<button data-focus="${id}" aria-pressed="${s.focus===id}" ${disabled(off)}><span>${label}</span><small>${effect}</small></button>`).join('')}</div>${!focusAvailable(s,s.focus)?`<p class="hint">이전 초점 ‘${escape(focusLabel(s))}’은 현재 목록에 없습니다. 가능한 초점을 고르거나 다음 생활 변화에서 전환할 수 있습니다.</p>`:''}<p class="hint focus-policy">지금 고른 초점은 가능한 동안 유지됩니다. 생활이 바뀌어 선택할 수 없게 되면 이유를 기록하고 바꿉니다.</p>`}${s.flags.educationOnLeave||s.flags.educationPaused?`<p class="hint">${s.flags.educationOnLeave?'휴학 중 · 과정과 남은 기간을 보관합니다.':'학비 부족으로 수강이 보류되어 있습니다.'}</p>`:''}</section>`; }
function referenceFeed(s,vm) {
 const histories=s.history.slice().reverse(),birth=s.history.find(h=>h.age===0&&h.category==='birth'&&h.structure==='birth');
 const birthIndex=birth?s.history.indexOf(birth):-1;
 const birthContext=birth?s.history.slice(birthIndex+1,birthIndex+3).filter((h,i)=>h.age===0&&h.source==='rule'&&h.category==='daily'&&h.title===['처음 함께 사는 사람들','자라게 될 생활의 자리'][i]):[];
 const groupedIds=new Set(birthContext.length?[birth.id,...birthContext.map(h=>h.id)]:[]);let birthShown=false;
 // One cohabitation choice records an action result and a story decision. Show
 // that adjacent, identical pair once; the existing full journal keeps both.
 const cohabitationPairs=new Map(),cohabitationActions=new Set();
 for(let i=1;i<s.history.length;i++){
  const action=s.history[i-1],decision=s.history[i];
  if(action.structure==='system:family:동거 논의와 함께 살기'&&action.category==='family'&&typeof decision.structure==='string'&&decision.structure.startsWith('relationship-direction:')&&decision.category==='relationships'&&action.source==='rule'&&decision.source==='rule'&&action.id!==decision.id&&action.age===decision.age&&action.year===decision.year&&action.text&&action.text===decision.text&&!action.lifeFacts&&!action.reference){
   cohabitationPairs.set(decision,action);cohabitationActions.add(action);
  }
 }
 const markedIds=new Set((s.historyMarks??[]).map(mark=>mark.historyId)),off=vm.busy||vm.readOnly||vm.viewing||s.status==='ended';
 const content=(h,interactive=true)=>{
  const opened=!!vm.panels?.['history:'+h.id],marked=markedIds.has(h.id),important=['birth','education','choice','ending'].includes(h.category);
  const text=interactive?`<button type="button" class="history-entry-text ${important?'important-event':''}" data-history-open="${escape(h.id)}" aria-expanded="${opened}">${escape(h.text||h.title)}</button>`:`<p class="${important?'important-event':''}">${escape(h.text||h.title)}</p>`;
  return text+(interactive&&opened?`<button type="button" class="history-mark-action" data-history-mark="${escape(h.id)}" data-marked="${!marked}" aria-pressed="${marked}" ${disabled(off)}>${marked?'★':'☆'} 기억할 순간</button>`:'')+`${h.lifeFacts?lifeFactDetail(h):''}${h.reference?`<details class="event-source"><summary>이 기록의 자료</summary><p>${escape(h.reference.summary??h.reference.label??'공개 역사 자료')} ${safeReferenceURL(h.reference.url)?`<a href="${escape(safeReferenceURL(h.reference.url))}" target="_blank" rel="noreferrer">출처</a>`:''}</p></details>`:''}`;
 };
 const ageLabel=h=>`${markedIds.has(h.id)?'<span class="history-star" aria-label="기억할 순간">★</span> ':''}${h.age}세`;

 const entries=histories.map(h=>{
  if(groupedIds.has(h.id)){if(birthShown)return '';birthShown=true;return `<article data-history-id="${escape(birth.id)}" class="birth-feed-entry" data-history-open="${escape(birth.id)}"><small>${ageLabel(birth)}</small><div>${content(birth)}<details class="birth-feed-context" data-birth-context-count="${birthContext.length}"><summary>출생 기록 자세히</summary>${birthContext.map(item=>`<div data-history-id="${escape(item.id)}"><strong>${escape(item.title)}</strong>${content(item,false)}</div>`).join('')}</details></div></article>`;}
  if(cohabitationActions.has(h))return '';
  const action=cohabitationPairs.get(h);
  return `<article data-history-id="${escape(h.id)}" data-history-open="${escape(h.id)}"${action?` data-related-history-id="${escape(action.id)}"`:''}><small>${ageLabel(h)}</small><div>${content(h)}</div></article>`;
 }).join('');
 return `<section class="reference-feed recent-life panel" aria-labelledby="recent-life-title"><div class="panel-heading"><h2 id="recent-life-title">인생 기록</h2><div class="feed-tools"><small>최근 순 · 줄을 누르면 ☆</small><button class="text-button" data-journal="chronicle">기록·메모 보기</button></div></div><p class="feed-context">${s.year}년, ${escape(countryName(s.countryId))}에서 흐르는 삶 · 이 기기에 기록됩니다.</p><div class="reference-feed-list">${entries||'<p>첫 기록을 기다립니다.</p>'}</div></section>`;
}
function lifeFactDetail(h) {
 const f=h.lifeFacts,labels={health:'건강',happiness:'행복',knowledge:'지식',social:'관계',energy:'활력'};
 const changes=Object.entries(f.statChanges??{}).filter(([,v])=>Number.isFinite(v)&&v!==0);
 const delta=v=>`${v>0?'+':''}${v}`;
 const parts=[];
 if(f.adultContext) {
  const stats=Object.entries(f.stats??{}).filter(([,v])=>Number.isFinite(v)).map(([key,v])=>`${escape(labels[key]??key)} ${Math.round(v*10)/10}${Number.isFinite(f.statChanges?.[key])?` (${delta(f.statChanges[key])})`:''}`);
  if(stats.length)parts.push(stats.join(' · '));
  const moneyFacts=[['income','수입'],['expense','지출'],['cash','현금']].filter(([k])=>Number.isFinite(f[k])).map(([k,label])=>`${label} ${amount(f[k])}`);
  if(moneyFacts.length)parts.push(moneyFacts.join(' · '));
  if(Number.isFinite(f.workSkill))parts.push(`업무 기술 ${f.workSkill}${Number.isFinite(f.workSkillChange)?` (${delta(f.workSkillChange)})`:''} · 현재 직무 경력 ${f.career.years}년`);
  if(f.education?.programId)parts.push(`남은 수강 ${f.education.yearsLeft}년${f.education.onLeave?' · 휴학':f.education.paused?' · 학비 부족으로 보류':''}`);
  if(f.hobbies?.length)parts.push(f.hobbies.map(h=>`${escape(HOBBIES.find(x=>x.id===h.id)?.label??h.id)} ${h.level}단계`).join(' · '));
  if(f.children?.length)parts.push(f.children.map(c=>`${escape(c.name)} 친밀도 ${c.closeness}`).join(' · '));
  if(f.choiceContext)parts.push(`${f.choiceContext.age}세에 고른 “${escape(f.choiceContext.label)}” 이후의 기록`);
 } else if(changes.length) parts.push(changes.map(([k,v])=>`${escape(labels[k]??k)} ${delta(v)}`).join(' · '));
 if(!parts.length)return '';
 return `<details class="life-fact-detail"><summary>그해 생활 변화</summary>${parts.map(p=>`<p>${p}</p>`).join('')}<small>그해에 저장한 게임 수치 · 합성 규칙</small></details>`;
}
function referenceFamily(s) {
 const friendIds=new Set(s.family.friends.map(p=>p.id));
 const people=familyRoster(s).filter(p=>!friendIds.has(p.id)&&!['friend','former_spouse','partner'].includes(p.relation));
 return `<section class="reference-family panel"><div class="panel-heading"><h2>가족과 삶</h2><button class="text-button" data-ui="family">자세히</button></div>${people.slice(0,7).map((p,i)=>{
  const {birth,unknownAbsent}=familyVisibility(s,p);
  const role=({mother:'어머니',father:'아버지',spouse:'배우자',child:'자녀',grandchild:'손주',great_grandchild:'증손',cohabitant:'동거인'})[birth?.role??p.relation]??(p.relation==='parent'?'부모 '+(i+1):p.name);
  const status=unknownAbsent?'현재 부재':p.alive?p.absent?'현재 부재':`${p.age}세`:`${p.deceasedAge??p.age}세에 사별`;
  return `<div class="family-line" data-family-person-id="${escape(p.id)}"><span>${escape(role)}</span><span>${status}${unknownAbsent?'':`<small>${escape(p.name)}</small>`}${birth?.occupationLabel&&birth.presentAtBirth!==false?`<small class="birth-occupation">출생 당시 ${escape(birth.occupationLabel)}</small>`:''}</span></div>`;
 }).join('')||'<p class="hint">기록된 가족 없음</p>'}${people.length>7?`<button class="text-button" data-ui="family">${people.length}명 모두 보기</button>`:''}</section>`;
}
function referenceCohort(s) { const c=getCohortComparison(s);return `<section class="reference-cohort panel"><div class="panel-heading"><h2>같은 시작을 맞은 사람들</h2><small>지금 이 나이에</small></div>${c.people.filter(p=>!p.player).map(p=>`<div class="cohort-line"><span><b>${escape(p.name)}</b><small>${escape(countryName(p.countryId))} · 합성 생애</small></span><span>${escape(p.status==='ended'||p.alive===false?`${p.deathAge??p.age??p.lifespan}세에 사별`:(p.age??s.age)<18?'어린 시절':p.career?.title??'직업 미기록')}</span></div>`).join('')}<button class="text-button" data-journal="comparison">생애 비교 자세히 보기</button></section>`; }
function referenceMap(s) { const tl=s.timeline??[],byAge=new Map(tl.map(t=>[t.age,t]));return `<section class="reference-map panel"><div class="panel-heading"><h2>인생 지도</h2><small>한 칸 = 1년</small></div><div class="year-grid">${Array.from({length:Math.max(100,s.age+1)},(_,age)=>{const y=byAge.get(age);return `<button data-map-age="${age}" class="${age===s.age?'current':''}" style="${y?`background:color-mix(in srgb,var(--teal) ${Math.min(90,20+y.happiness*.7)}%,var(--surface))`:''}" aria-label="${age}세${y?`, 행복 ${Math.round(y.happiness)}`:', 아직 기록 없음'}" title="${age}세${y?` · 행복 ${Math.round(y.happiness)}`:''}" ${disabled(!y)}>${age===s.age?'<span class="sr-only">현재</span>':''}</button>`;}).join('')}</div><p class="hint">한 칸 = 1년 · 진할수록 행복했던 해<br>테두리 칸 = 현재 나이 · 합성 게임 수치</p></section>`; }
function referenceSurvival(s) { const c=getCohortComparison(s);return `<section class="reference-survival panel"><div class="panel-heading"><h2>생존 곡선</h2><small>동기 표본 ${c.sampleSize??5}명</small></div>${renderChart(c.survival,'value',{color:'var(--teal)',label:'합성 동기 표본의 생존 비율',unit:'%'})}<p class="hint">${c.projected?'마지막 시점 이후는 모형 투영입니다.':'현재 나이까지 관찰한 합성 인물 표본입니다.'} 국가의 실제 생존 통계가 아닙니다.</p></section>`; }
function referenceCountry(s) { const c=getCountry(s.countryId);return `<section class="reference-country panel"><h2>${escape(c.name)}</h2><dl><dt>생활 환경</dt><dd>${s.city==='urban'?'도시':'농촌'}</dd><dt>지역 설계</dt><dd>${escape(c.designProfile)}</dd><dt>교육 환경</dt><dd>${c.education}</dd><dt>건강 환경</dt><dd>${c.health}</dd><dt>소득 기준</dt><dd>${amount(c.income)}</dd><dt>출생 추첨</dt><dd>${s.flags.demographicBasis==='reference-2023'?'2023 공개 자료':'합성 분포'}</dd></dl><p class="hint">교육·건강·소득은 합성 설계값입니다. G는 게임 포인트이며 실제 화폐·PPP 환산이 아닙니다.</p><button class="text-button" data-ui="help">자료와 규칙 안내</button></section>`; }
function referenceDecision(s,vm) { const p=s.pending;if(!p||s.status==='ended')return '';const off=vm.busy||vm.readOnly||vm.viewing;if(vm.minimized)return `<aside class="decision-dock" aria-label="대기 중인 결정"><span><b>결정을 기다리고 있어요</b><small>${escape(p.title)}</small></span><button class="primary" data-ui="minimize">다시 펼치기</button></aside>`;return `<div class="decision-scrim"><section class="reference-decision" id="decision-dialog" role="dialog" aria-modal="true" aria-labelledby="decision-title"><header><span>${isMilestoneReflection(s)?'잠시 멈춤':'중대 결정'}</span><span>${s.age}세 · ${s.year}년</span><button data-ui="minimize">잠깐 내려 두기 ▾</button></header><div class="reference-decision-body">${isMilestoneReflection(s)?reflectionDecision(s,vm):`<h2 id="decision-title" tabindex="-1">${escape(p.title)}</h2><p>${escape(p.body)}</p><div class="choices">${p.choices.map((choice,i)=>`<button class="choice" data-choice="${escape(choice.id)}" data-decision="${escape(p.id)}" ${disabled(off)}><span class="choice-number">${i+1}</span><span class="choice-content"><strong>${escape(choice.label)}</strong>${choice.description?`<small>${escape(choice.description)}</small>`:''}</span></button>`).join('')}</div><button class="small-button auto-offer" data-ui="toggle-auto" ${disabled(off)}>이제부터 결정을 자동으로 맡기기</button>`}</div></section></div>`; }
function referenceToolbar(s,session,vm) { const off=vm.busy||vm.readOnly||vm.viewing||s.status==='ended',waiting=!!s.pending,status=waiting?'선택을 기다립니다.':vm.playing?'시간이 흐르는 중':vm.pauseReason==='reloaded'?'저장된 삶을 불러와 안전하게 멈췄습니다.':'시간을 잠시 멈췄습니다.';return `<header class="life-toolbar"><div class="toolbar-inner"><span class="life-brand">80억 분의 <em>1</em></span><div class="life-age"><strong>${s.age}</strong>세</div><div class="year-progress"><span>${s.year}년 · ${escape(s.name)} · <span data-year-pace>1년 ≈ ${paceSeconds(s)}초</span></span><i><b id="flow-progress"></b></i></div><div class="life-controls"><button data-ui="play" aria-pressed="${vm.playing}" aria-label="${vm.playing?'시간 흐름 잠시 멈추기':'시간 흐름 이어가기'}" ${disabled(off)}>${vm.playing?'Ⅱ':'▸'}<span class="desktop-only"> ${vm.playing?'멈춤':'계속'}</span></button><div class="speed-buttons" aria-label="진행 속도">${[1,2,4,8,12,16].map(n=>`<button data-speed="${n}" aria-pressed="${s.settings.speed===n}" ${disabled(off)}>${n}×</button>`).join('')}</div><button data-command="nextDecision" ${disabled(off||waiting)}><span class="desktop-only">다음 결정까지</span><span class="mobile-only">다음</span> »</button><div class="desktop-controls"><button data-ui="toggle-auto" aria-pressed="${s.settings.auto}" ${disabled(off)}>자동 결정</button><button data-ui="music" aria-pressed="${session.preferences.music}">♪ 음악</button><button data-ui="toggle-reflection" aria-pressed="${!!s.settings.reflectionStops}" ${disabled(off)}>✎ 생각 남기기</button><button data-ui="theme" aria-label="화면 밝기 바꾸기">◐</button></div><details id="life-more" class="life-more" ${vm.moreOpen?'open':''}><summary aria-label="더 보기">⋯</summary><nav><button class="mobile-menu-item" data-ui="toggle-auto" aria-pressed="${s.settings.auto}">자동 결정</button><button class="mobile-menu-item" data-ui="music">♪ 음악</button><button class="mobile-menu-item" data-ui="toggle-reflection" aria-pressed="${!!s.settings.reflectionStops}">✎ 생각 남기기</button><button class="mobile-menu-item" data-ui="theme">◐ 화면 바꾸기</button><button data-ui="family">가족과 삶 보기</button><button data-ui="finance">돈 쓰기 · 투자 열기</button><button data-ui="systems">생활 선택 더 보기</button><button data-ui="note">메모 남기기</button><button data-ui="records">전생의 집 · 기록 관리</button><button data-ui="settings">설정</button><button data-ui="help">규칙·자료 안내</button><button data-ui="new-life">나가기 · 새 삶</button></nav></details></div></div><div class="flow-status sr-only" data-flow-state="${waiting?'waiting':vm.playing?'running':'paused'}"><span>${status}</span><span id="flow-clock"></span></div><div id="play-notice" class="play-notice" role="status" aria-live="polite" hidden></div></header>`; }
export function renderLife(s,session,vm) {return `${referenceToolbar(s,session,vm)}<div class="reference-wrap life-wrap">${vm.viewing?'<div class="readonly-strip">보관된 삶을 읽는 중입니다. <button data-ui="continue">현재 삶으로 돌아가기</button></div>':''}${ending(s)}<div class="life-layout"><aside class="life-left">${lifeIdentity(s)}${baseStats(s)}</aside><div class="life-center"><section class="reference-scene panel">${scene(s)}<details><summary>${escape(countryName(s.countryId))} · ${escape(getResidenceLabel(s))} · ${escape(HOME[s.finance.home]??s.finance.home)} <span>▾</span></summary><p>${escape(describeScene(s).label)}</p></details></section>${baseStats(s,true,vm)}${referenceFocus(s,vm)}${referenceFeed(s,vm)}</div><aside class="life-right">${referenceFamily(s)}${referenceCohort(s)}${referenceMap(s)}${referenceSurvival(s)}${referenceCountry(s)}</aside></div><p class="life-scope">비공식 로컬 재현 · 자체 코드·픽셀 그림 · 생활 규칙 합성 · 외부 AI 미연결</p></div>${referenceDecision(s,vm)}`; }
export function renderSystemsDialog(s,session,vm) { if(vm.tab==='finance')return renderFinanceSheet(s,session,vm);return dialogShell(vm.tab==='finance'?'돈 쓰기 · 투자':'생활 선택',`<p class="dialog-context">모은 돈 ${amount(s.finance.cash)} · 고르는 동안 시간은 기다립니다.</p>${actions(s,{...vm,panels:{...vm.panels,systems:true}},session.preferences.locale)}<details class="supplemental"><summary>반복 지출·자동 응답·수동 계획</summary>${sidebar(s,vm)}</details>`); }
export function renderJournalDialog(s,vm) { return dialogShell('삶의 기록과 메모',`<nav class="journal-tabs" role="tablist" aria-label="삶의 기록">${[['chronicle','기록·메모'],['map','인생 지도'],['finance','재정 흐름'],['comparison','같은 시작']].map(([id,label])=>`<button id="journal-${id}" role="tab" aria-selected="${vm.journal===id}" data-journal="${id}">${label}</button>`).join('')}</nav><div id="journal-content">${journalContent(s,vm)}</div>`); }

function investmentOptionLabel(option){
 const investment=INVESTMENTS.find(item=>item.id===option.value);
 if(!investment)return option.label;
 const percent=value=>(value*100).toLocaleString('ko-KR',{maximumFractionDigits:1});
 // These are the local annual rule inputs, not the reference game's real-return
 // examples. The catalog's fee field is not charged annually by the engine.
 return `${option.label} · 연 기준 ${percent(investment.return)}%, 변동 ±${percent(investment.risk)}%p${investment.id==='global'?' · 환율 변동 별도':''}`;
}
function renderFinanceSheet(s,session,vm){
 const all=getAvailableActions(s),finance=all.filter(a=>normalizeGroup(a.group)==='finance'),off=vm.busy||vm.readOnly||vm.viewing||s.status==='ended',child=s.age<18;
 const settingIds=['allocate','insurance','diet','social_budget','will'],settings=settingIds.map(id=>all.find(a=>a.id===id)).filter(Boolean);
 const availableSettings=settings.filter(a=>!a.disabledReason),laterSettings=settings.filter(a=>a.disabledReason);
 const spending=finance.filter(a=>!a.options?.length&&!a.id.startsWith('auto_')&&!a.disabledReason).slice(0,8);
 const childhood=['family_time','friend','study','recovery'].map(id=>all.find(a=>a.id===id)).filter(a=>a&&!a.disabledReason&&!a.options?.length);
 const dinner=all.find(a=>a.id==='dinner'),autoDinner=all.find(a=>a.id==='auto_dinner');
 const interest=all.find(a=>a.id==='career_interest');
 const visible=child?childhood:[...spending.filter(a=>a.id!=='dinner'),...(interest?[interest]:[])];
 const dinnerSkipped=s.automations.skipped?.dinner,dinnerStatus=dinnerSkipped?`최근 ${dinnerSkipped.age}세: ${({insufficient_funds:'자금 부족',reserve_protected:'생활 준비금 유지',insufficient_reserve:'생활 준비금 부족',no_targets:'함께할 가족·친구 없음',no_relationships:'함께할 가족·친구 없음'})[dinnerSkipped.reason]??'실행 조건 미충족'}`:s.automations.lastRun?.dinner!=null?`최근 실행 ${s.automations.lastRun.dinner}세`:'';
 const item=a=>`<form class="finance-row" data-action-form="${escape(a.id)}"><button type="submit" ${disabled(off||a.disabledReason)}><span><strong>${escape(a.label)}</strong><small>${a.id==='dinner'?'관계 +4 · 행복 +2':escape(a.description??'')}</small></span><span>${a.cost>0?amount(a.cost):'비용 없음'}<small>${escape(a.disabledReason??'선택하기')}</small></span></button></form>`;
 const setting=a=>`<section><h3>${escape(a.id==='allocate'?'여유 자금 굴리기':a.label)}</h3><div class="finance-option-chips">${a.options.map(o=>`<button data-action-option="${escape(a.id)}" data-option-value="${escape(o.value)}" aria-pressed="${String(selectedAction(s,a))===String(o.value)}" ${disabled(off||a.disabledReason)}>${escape(a.id==='allocate'?investmentOptionLabel(o):o.label)}</button>`).join('')}</div>${a.id==='allocate'?'<p class="hint investment-rule-note">합성 게임의 연간 기준값이며 수익을 보장하지 않습니다. 표시한 변동폭은 기본 수익 계산에 사용됩니다. 수익률 상·하한과 해외 지수의 가상 환율에 따라 최종 결과가 달라집니다.</p>':''}<p class="hint">${escape(a.disabledReason??a.description??'')}</p></section>`;
 return dialogShell('돈 쓰기 · 투자',`<section class="finance-sheet ${child?'child-finance':''}"><h2>${child?'내 현금 기록':'모은 돈'} <span data-personal-cash="${s.finance.cash}">${amount(s.finance.cash)}</span></h2>${child?`<div class="household-context"><span>우리 집 형편</span><strong>${escape(({low:'빠듯한 살림',middle:'안정된 살림',high:'여유 있는 살림'})[s.household]??'미기록')}</strong><small>${escape(HOME[s.finance.home]??s.finance.home)} · 부모님의 재산과 별도</small></div><p>위 금액은 이 인생에 기록된 게임 자금입니다. 용돈이나 가족 전체 재산을 뜻하지 않으며, 실제 화폐·PPP로 환산하지 않습니다.</p>`:'<p>G는 게임 포인트입니다. 쓰는 만큼 생활과 미래가 바뀝니다. 고르는 동안 시간은 기다립니다.</p>'}${child?'<h3 class="finance-action-heading">지금 할 수 있는 생활 선택</h3>':''}<div class="finance-choices">${dinner?item(dinner):''}${autoDinner?`<div class="finance-auto-dinner"><button type="button" role="switch" aria-checked="${!!s.automations.dinner}" aria-label="외식·선물을 해마다 자동으로 하기" data-action-option="auto_dinner" data-option-value="${s.automations.dinner?'off':'on'}" ${disabled(off||autoDinner.disabledReason)}><span class="check-mark" aria-hidden="true">${s.automations.dinner?'✓':''}</span><span>해마다 자동으로</span><small>연 ${amount(dinner?.cost??150)}</small></button>${autoDinner.disabledReason||dinnerStatus?`<p class="hint">${escape(autoDinner.disabledReason??dinnerStatus)}</p>`:''}<details class="finance-dinner-rules"><summary>비용·실행 조건</summary><p>${escape(dinner?.description??'')}</p><p>${escape(autoDinner.description??'')}</p></details></div>`:''}${visible.length?`<details class="finance-other"><summary>다른 생활 선택</summary>${visible.map(item).join('')}</details>`:!dinner?'<p class="hint">현재 조건에서 바로 실행할 재정 행동이 없습니다. 아래에서 각 행동의 조건을 살펴보세요.</p>':''}</div><details class="finance-lifestyle" data-panel="financeLifestyle" ${vm.panels?.financeLifestyle?'open':''}><summary>생활 방식 <small>${'돈 맡기기: '+escape(INVESTMENTS.find(i=>i.id===s.finance.allocation)?.label??s.finance.allocation)}</small></summary>${availableSettings.map(setting).join('')}${laterSettings.length?`<details class="finance-future"><summary>아직 사용할 수 없는 설정 ${laterSettings.length}개 · 조건 보기</summary>${laterSettings.map(setting).join('')}</details>`:''}<details class="supplemental"><summary>반복 지출·수동 계획</summary>${sidebar(s,vm)}</details></details><details class="finance-all" data-panel="financeAll" ${vm.panels?.financeAll?'open':''}><summary>전체 재정 선택과 조건 보기</summary>${actions(s,{...vm,panels:{...vm.panels,systems:true}},session.preferences.locale)}</details><div class="finance-sheet-close"><button class="secondary" data-ui="close-dialog">닫기</button></div></section>`);
}
